window.MINDCRAFT_CONTENT = {
  tracks: [
    { id:'observation', code:'01', name:'Observation', subtitle:'Notice before you interpret', description:'Build deliberate attention and recall. Record what a camera could verify before attaching a story to it.', prerequisite:'Open to all', lessons:[['See the detail','Attention is selective. Slow down, name concrete details, then check what you missed. A careful note describes what was visible—not why it happened.'],['Separate signal from story','A detail becomes an interpretation when you assign a cause or intention. Keep both in view, but label them differently.'],['Test the first impression','Make at least two plausible explanations before deciding. Look for the next observable fact that would distinguish them.']] },
    { id:'psychology', code:'02', name:'Psychology', subtitle:'Think in possibilities', description:'Use basic cognitive science to question assumptions, recognize bias, and stay curious about other explanations.', prerequisite:'Open to all', lessons:[['Cues are not verdicts','A pause, gaze shift, or fidget has many possible causes. Context, a person’s baseline, and corroboration matter far more than one cue.'],['Notice your own bias','Confirmation bias makes matching details feel more persuasive. Ask what evidence would change your mind, and actively look for it.'],['Calibrate confidence','Use words such as possible, likely, and well-supported. Confidence should follow the quality and quantity of evidence.']] },
    { id:'criminology', code:'03', name:'Criminology', subtitle:'Follow evidence, not hunches', description:'Practice high-level case reasoning: timelines, source reliability, corroboration, and the limits of evidence.', prerequisite:'Open to all', lessons:[['Build a neutral timeline','Put reported events in order and distinguish the event time from the time it was remembered or recorded. Mark gaps rather than filling them.'],['Check source quality','Ask how a fact was obtained, what could distort it, and whether an independent source supports it. A lead is not a finding.'],['Keep alternatives alive','Construct more than one explanation that fits the known facts. Seek disconfirming information and preserve uncertainty.']] },
    { id:'interviewing', code:'04', name:'Behaviour & interviewing', subtitle:'Ask clearly. Listen fully.', description:'Practice respectful, open-ended conversation and careful interpretation. No coercion, manipulation, or lie-detection shortcuts.', prerequisite:'Open to all', lessons:[['Invite a full account','Open prompts such as “What happened next?” let people answer in their own words. Avoid suggesting facts they have not offered.'],['Reflect, then clarify','Briefly summarize what you heard and ask a neutral follow-up. This checks understanding without implying that hesitation or emotion proves anything.'],['Mind the context','Memory changes with stress, time, attention, and question wording. Seek corroboration; never infer truthfulness from demeanor alone.']] },
    { id:'strategy', code:'05', name:'Strategic thinking', subtitle:'Choose the next useful step', description:'Compare options, constraints, risks, and information value before acting. Prefer safe, reversible moves when facts are thin.', prerequisite:'Open to all', lessons:[['Name the objective','Define what a good outcome looks like and what must not be compromised—safety, fairness, time, or trust.'],['Compare options','For each move, consider likely benefits, downside, reversibility, and what new information it would produce.'],['Update the plan','A plan is a hypothesis too. Set a check-in point, name what would change your choice, and revise when new evidence arrives.']] }
  ],
  exercises: [
    { id:'observe-detail', track:'observation', title:'The waiting room', format:'Detail recall', difficulty:1, observe:'At 9:10, a visitor in a rust-colored coat placed a folded newspaper on the chair beside the window. A paper cup sat on the counter. A wall clock showed 9:12. The receptionist was speaking on a blue phone.', prompt:'Which detail was directly described?', options:[['A visitor left a folded newspaper on the chair by the window.',true],['The visitor was anxious about an appointment.',false],['The receptionist was trying to hide a conversation.',false]], explanation:'The newspaper, chair, and window are visible details in the account. Anxiety or secrecy would be interpretations not supported by the scene.', observation:'A rust-colored coat, folded newspaper, chair by a window, cup, clock, blue phone.', inference:'The visitor felt nervous, or the receptionist was being secretive.', alternative:'The visitor may simply have set the paper down; the receptionist may be handling ordinary work.' },
    { id:'observe-inference', track:'observation', title:'Fact or interpretation?', format:'Observation vs. inference', difficulty:2, scenario:'During a meeting, Jordan checked their watch twice, asked for the agenda, and left at 3:30, the time they had mentioned earlier.', prompt:'Which note stays closest to observable facts?', options:[['Jordan was bored and wanted to escape.',false],['Jordan checked a watch twice, asked for the agenda, and left at 3:30.',true],['Jordan disliked the presenter.',false]], explanation:'A useful field note records observable actions and timing. Motive is a separate hypothesis that needs more information.', observation:'Two watch checks, an agenda request, and a departure at 3:30.', inference:'Jordan was bored, impatient, or disliked the presenter.', alternative:'Jordan may have had a scheduled commitment or wanted to follow the agenda closely.' },
    { id:'psych-cue', track:'psychology', title:'One cue, many causes', format:'Alternative explanations', difficulty:1, scenario:'In a calm conversation, Lee pauses before answering a question and rubs one hand.', prompt:'What is the most responsible interpretation?', options:[['That behavior proves Lee is lying.',false],['The pause and hand movement are observations; their meaning is uncertain.',true],['Lee is hiding something because truthful people answer quickly.',false]], explanation:'A single behavioral cue is not a reliable truth test. Stress, habit, cold hands, careful recall, or a pause to think could all fit.', observation:'A pause before an answer and one hand rub.', inference:'Dishonesty, anxiety, or concealment.', alternative:'Lee may be thinking, uncomfortable, distracted, or simply have a habitual movement.' },
    { id:'psych-bias', track:'psychology', title:'Check the confirmation bias', format:'Bias check', difficulty:2, scenario:'You suspect a staff member made an inventory error. You notice one count that supports your suspicion and stop checking.', prompt:'What is the best next reasoning move?', options:[['Collect only more examples that support the suspicion.',false],['Look for independent records and actively check what would disconfirm the suspicion.',true],['Treat the first matching count as proof of intent.',false]], explanation:'Confirmation bias makes supporting examples feel decisive. Independent records and disconfirming checks help test the hypothesis.', observation:'One count differs from the expected inventory.', inference:'A particular person deliberately caused the discrepancy.', alternative:'A receiving error, counting mistake, or timing difference could explain it.' },
    { id:'crime-timeline', track:'criminology', title:'The timeline gap', format:'Timeline analysis', difficulty:1, scenario:'A report says a side door was found open at 8:40. A camera shows a delivery at 8:15, but the camera does not show the door. The first staff member arrived at 8:30.', prompt:'What can be concluded from these facts alone?', options:[['The delivery driver opened the door.',false],['The door was found open at 8:40; when or by whom it opened is not established.',true],['The first staff member must have left it open.',false]], explanation:'The observations set bounds on what is known, not who caused it. The camera angle and timing leave a gap.', observation:'Door found open at 8:40; delivery at 8:15; staff arrival at 8:30.', inference:'The delivery driver or staff member opened it.', alternative:'The door may have been open earlier, or another event may explain the timing.' },
    { id:'crime-evidence', track:'criminology', title:'A lead is not a finding', format:'Evidence evaluation', difficulty:2, scenario:'A fictional case file contains a second-hand account, a timestamped receipt, and an incomplete camera view. The three records overlap in time but do not identify who acted.', prompt:'Which next step best protects the quality of the reasoning?', options:[['Name the person mentioned in the account as responsible.',false],['Record each source and its limits, then seek independent corroboration before drawing a conclusion.',true],['Ignore any evidence that does not fit the first account.',false]], explanation:'Source provenance, limitations, and independent corroboration matter. A lead can guide a question without becoming proof.', observation:'Three records overlap in time; none identifies an actor.', inference:'The person named second-hand caused the event.', alternative:'The account may be mistaken; the receipt may be unrelated; the camera may omit a different actor.' },
    { id:'interview-open', track:'interviewing', title:'A better follow-up', format:'Interviewing technique', difficulty:1, scenario:'A colleague says, “I heard a noise near the storeroom, then I went to check.” You want their account without steering it.', prompt:'Which follow-up is the most neutral?', options:[['“You saw someone leave through the back door, right?”',false],['“What happened next?”',true],['“Why did you wait so long to report it?”',false]], explanation:'An open prompt invites a fuller account in the speaker’s own words. Leading questions can introduce details and shape later recall.', observation:'The colleague reported hearing a noise and checking the storeroom.', inference:'They saw a particular person or deliberately delayed.', alternative:'They may have heard a routine sound, or the timeline may need clarification.' },
    { id:'interview-corroborate', track:'interviewing', title:'Demeanor is not a detector', format:'Behavioural reasoning', difficulty:2, scenario:'Two people describe the same meeting. One looks directly at you; the other looks away while recalling details. Their accounts differ on the time.', prompt:'What is the fairest next move?', options:[['Trust the person who made more eye contact.',false],['Compare the specific claims with independent records and ask each person neutral clarifying questions.',true],['Assume the person who looked away was deceptive.',false]], explanation:'Eye contact varies with culture, personality, neurotype, stress, and context. It cannot resolve a factual difference; check claims against records and clarify neutrally.', observation:'Different gaze behavior and a disagreement about time.', inference:'One person is truthful because of demeanor.', alternative:'Either person could be mistaken; records may also have limits or clock differences.' },
    { id:'strategy-next-step', track:'strategy', title:'Choose the next useful step', format:'Strategic decision', difficulty:1, scenario:'You have ten minutes, an incomplete timeline, and two possible explanations. One next step is quick and reversible; the other is public and difficult to undo.', prompt:'Which strategy is strongest while evidence is thin?', options:[['Make the public accusation now to force a response.',false],['Take the safe, reversible step that checks a key fact, then reassess.',true],['Choose whichever explanation feels most convincing.',false]], explanation:'When uncertainty is high, a low-risk, reversible action can improve information without causing avoidable harm.', observation:'There are two explanations, little time, and different action costs.', inference:'A forceful move will reveal the truth.', alternative:'A public accusation may contaminate accounts, damage trust, or unfairly harm someone.' },
    { id:'strategy-sequence', track:'strategy', title:'Sequence the work', format:'Sequencing', difficulty:2, scenario:'A fictional incident needs review. You must preserve a fragile record, write down your own first impression, and compare possible explanations.', prompt:'What order best reduces bias and protects information?', options:[['Choose a suspect, then collect details that fit.',false],['Secure the record, write neutral observations, then compare multiple explanations against it.',true],['Discuss your favorite theory first, then ask witnesses leading questions.',false]], explanation:'Preserving records and separating observation from interpretation before testing alternatives reduces avoidable bias.', observation:'A fragile record and an untested first impression are present.', inference:'The first theory should determine what evidence matters.', alternative:'The initial account may be incomplete; later evidence can change the best explanation.' },
    { id:'observe-location', track:'observation', title:'Write what you can verify', format:'Observation note', difficulty:1, scenario:'At 7:40, a note says the bicycle rack was empty. At 7:52, a receipt records a purchase nearby. The note says nothing about the intervening minutes.', prompt:'Which note stays within the evidence?', options:[['A bicycle was present at 7:52.',false],['The rack was recorded as empty at 7:40; the receipt is nearby at 7:52.',true],['Someone removed the bicycle because they saw the note-taker.',false]], explanation:'The two time-stamped details can be recorded without assuming what happened between them.', observation:'A note records an empty rack at 7:40; a nearby receipt is timestamped 7:52.', inference:'A particular person removed or saw a bicycle.', alternative:'The receipt may be unrelated, and the rack could have changed at any time after the note.' },
    { id:'psych-context', track:'psychology', title:'A quiet conversation', format:'Context check', difficulty:1, scenario:'A teammate is quieter than usual during one afternoon meeting and asks to review the notes later.', prompt:'What is the fairest first interpretation?', options:[['They are angry with the group.',false],['Those are observations; the reason for the change is unknown.',true],['They are disengaged and should be confronted.',false]], explanation:'A change from someone’s usual pattern may invite a considerate check-in, but it does not identify a cause.', observation:'The teammate spoke less and requested the notes.', inference:'Anger, disengagement, or a conflict.', alternative:'They may be tired, unwell, managing another responsibility, or simply prefer to review written notes.' },
    { id:'crime-source', track:'criminology', title:'Keep the clock in view', format:'Source evaluation', difficulty:1, scenario:'A written note says a package arrived “around noon.” A delivery scan records 12:17, but the device time zone has not been checked.', prompt:'What is supported right now?', options:[['Both sources independently confirm an exact noon arrival.',false],['The note gives an approximate time and the scan records 12:17; clock settings remain a limitation.',true],['An unchecked time zone means the scan was falsified.',false]], explanation:'State each source and its precision. An unchecked setting limits timestamp confidence but is not evidence of tampering.', observation:'One approximate note and one 12:17 scan with unverified time-zone settings.', inference:'The exact arrival time or intent is known.', alternative:'The clock may be accurate or offset; checking its configuration can clarify the discrepancy.' },
    { id:'interview-open-start', track:'interviewing', title:'Invite the account', format:'Open question', difficulty:1, scenario:'Sam says, “I finished the call and then went outside.” You want to understand the sequence from Sam’s point of view.', prompt:'Which question leaves the most room for Sam’s own account?', options:[['“You went outside because the call upset you?”',false],['“What happened after you finished the call?”',true],['“Why did you leave without telling anyone?”',false]], explanation:'The open follow-up asks about sequence without suggesting a motive, emotion, or unreported action.', observation:'Sam says the call ended and they went outside.', inference:'They were upset or intended to leave secretly.', alternative:'They may have needed fresh air, had a plan, or be describing a routine transition.' },
    { id:'strategy-constraints', track:'strategy', title:'Name the constraint', format:'Decision framing', difficulty:1, scenario:'You have two plausible explanations and only enough time to check one detail. Privacy and fairness matter; no one is at immediate risk.', prompt:'What is the best first planning step?', options:[['Choose the explanation you find most compelling.',false],['Clarify the decision you need to make and the privacy constraint before selecting a proportionate check.',true],['Question everyone until one account changes.',false]], explanation:'A defined objective and clear safeguards help keep the next step proportionate and useful.', observation:'There is limited time, uncertainty, and an explicit privacy concern.', inference:'Pressure or repeated questioning will resolve the uncertainty.', alternative:'A focused, consent-respecting check may answer the decision-relevant question without unnecessary intrusion.' },
    { id:'observe-conflict', track:'observation', title:'Two notes, one discrepancy', format:'Contradiction spotting', difficulty:3, scenario:'A neutral note at 10:05 says the folder was on the left side of the desk. A second note at 10:20 says it was on the shelf. Neither note records who moved it or whether the desk was checked again.', prompt:'What is the most careful next statement?', options:[['Someone moved the folder to hide it.',false],['The notes differ about location; the movement and timing are not established.',true],['The second note must be false.',false]], explanation:'A discrepancy identifies a question to clarify, not a cause or a person. Check the source, timestamps, and any intervening observation.', observation:'Two notes describe different folder locations at different times.', inference:'Someone deliberately moved it or one note-taker is dishonest.', alternative:'A person may have moved it routinely, the times may be approximate, or a note could be mistaken.' },
    { id:'psych-calibration', track:'psychology', title:'Calibrate the claim', format:'Confidence calibration', difficulty:3, scenario:'Two independent records support one timeline, while a third source conflicts but has an unclear timestamp. No source identifies intent.', prompt:'Which summary best matches the evidence?', options:[['The person named in one source definitely acted intentionally.',false],['The timeline is moderately supported; the conflicting timestamp and intent remain unresolved.',true],['Because one source conflicts, no information is useful.',false]], explanation:'Confidence can be mixed: evidence may support timing while leaving identity or intent unknown. State which part is supported and which is not.', observation:'Two records support timing; one source has an unclear timestamp; none establishes intent.', inference:'Support for an event time proves who acted and why.', alternative:'The record may support sequence while additional evidence is needed for identity, cause, or intent.' },
    { id:'crime-provenance', track:'criminology', title:'Trace the source', format:'Evidence provenance', difficulty:3, scenario:'A case review contains a copied note with no author listed, a system export with uncertain clock settings, and a separate record whose time was independently checked.', prompt:'Which review step is most informative and fair?', options:[['Treat the copied note as definitive because it matches the first theory.',false],['Document each item’s origin, timing limits, and handling, then compare only what can be reliably corroborated.',true],['Assume any uncertain timestamp proves tampering.',false]], explanation:'Provenance and clock reliability affect what a record can support. Uncertainty is a limitation to investigate—not evidence of deliberate manipulation.', observation:'Three records have different provenance and timing reliability.', inference:'An uncertain time proves that a record was altered.', alternative:'Clock settings, export processes, or missing context could explain the discrepancy.' },
    { id:'interview-memory', track:'interviewing', title:'Protect an independent account', format:'Memory and context', difficulty:3, scenario:'A willing participant says they discussed an event with a friend before your conversation. You want to understand what they personally recall without steering them.', prompt:'What is a respectful, low-contamination approach?', options:[['Tell them what the friend said, then ask them to agree or disagree.',false],['Explain your purpose, invite an uninterrupted account in their own words, and ask what they remember versus learned later.',true],['Repeat the most dramatic detail until they confirm it.',false]], explanation:'Separating personal recollection from later information helps interpret the account. Clear purpose, consent, and neutral prompts reduce suggestion.', observation:'The participant heard a friend’s account before this conversation.', inference:'Their memory is worthless or intentionally changed.', alternative:'They may retain accurate independent details and can distinguish those from later discussion.' },
    { id:'strategy-value', track:'strategy', title:'Spend effort where it can change a decision', format:'Information-value strategy', difficulty:3, scenario:'Three explanations fit a report. You can spend five minutes verifying a low-impact detail, or ask permission to check one independent record that would distinguish two of the explanations. Both options are safe.', prompt:'How should you choose the next step?', options:[['Choose the record check if it can fairly distinguish the explanations; state what result would change your view.',true],['Pick whichever explanation matches your first impression.',false],['Collect every available detail before deciding whether any is useful.',false]], explanation:'A useful next step is relevant to a real decision, proportionate, and capable of updating your view. Define in advance how each result will count.', observation:'Several explanations fit; one safe check may discriminate between two.', inference:'More information is always useful, regardless of relevance or consent.', alternative:'A low-impact detail may not change the decision; the independent record may also have limitations.' },
    { id:'obs-blue-mug', track:'observation', title:'The blue mug', format:'Detail recall', difficulty:1, observe:'At 8:05, a man in a green jacket placed a blue mug on the table beside the window. A black pen lay next to a closed notebook. A wall clock showed 8:07. A radio played quietly on the shelf.', prompt:'Which detail was directly described?', options:[['A man placed a blue mug on the table beside the window.',true],['The man was tired after a long night.',false],['The radio was playing his favourite station.',false]], explanation:'The mug, table, and window are visible details in the scene. Tiredness and musical taste are interpretations with no support here.', observation:'A green jacket, blue mug, table by a window, black pen, closed notebook, clock, radio.', inference:'The man was tired, or the radio station was his favourite.', alternative:'The man may have set the mug down routinely; the radio may belong to the room, not to him.' },
    { id:'obs-red-backpack', track:'observation', title:'The red backpack', format:'Detail recall', difficulty:1, observe:'At 3:20, a student with a red backpack sat on the bench near the library door. A water bottle stood on the ground beside the bench. A poster on the wall showed a train timetable. The library door was open.', prompt:'Which detail was directly described?', options:[['The student was waiting for a friend.',false],['A student with a red backpack sat on the bench near the library door.',true],['The student had missed the train.',false]], explanation:'The backpack, bench, and library door are stated in the scene. Waiting for a friend and missing a train are guesses, not observations.', observation:'A red backpack, bench, library door, water bottle, poster, open door.', inference:'The student was waiting for someone, or had missed a train.', alternative:'The student may be resting, studying, or waiting for the library to quieten.' },
    { id:'obs-green-umbrella', track:'observation', title:'Three objects by the door', format:'Count the details', difficulty:1, observe:'At 6:40, a green umbrella leaned against the wall by the front door. A pair of brown boots stood beside it. A grey scarf hung on the hook above the boots. The hallway light was on.', prompt:'Which list matches the scene exactly?', options:[['A green umbrella, brown boots, and a blue scarf.',false],['A green umbrella, black boots, and a grey scarf.',false],['A green umbrella, brown boots, and a grey scarf.',true]], explanation:'All three objects and their colours are stated directly. Changing a colour makes the list wrong, even if the objects are right.', observation:'A green umbrella, brown boots, grey scarf, hook, hallway light.', inference:'The owner had just come in from the rain.', alternative:'The items may have been left there earlier; the light may be on for another reason.' },
    { id:'obs-yellow-notepad', track:'observation', title:'The yellow notepad', format:'Detail recall', difficulty:1, observe:'At 11:15, a yellow notepad lay open on the kitchen counter. A pencil rested across the top page. A glass of water stood beside the sink. A clock on the wall showed 11:16.', prompt:'Which detail was directly described?', options:[['Someone was planning a surprise party.',false],['A yellow notepad lay open on the kitchen counter with a pencil across the top page.',true],['The writer had run out of ideas.',false]], explanation:'The notepad, pencil, and counter are visible details. A party plan and a lack of ideas are not stated anywhere in the scene.', observation:'A yellow notepad, pencil, glass of water, sink, wall clock.', inference:'Someone was planning a party, or had run out of ideas.', alternative:'The notepad may hold a shopping list, a recipe, or notes from a phone call.' },
    { id:'obs-grey-coat-hook', track:'observation', title:'The coat hook', format:'What changed?', difficulty:1, observe:'At 9:00, a grey coat hung on the second hook by the office door. A black umbrella stood in the corner. At 9:30, the second hook was empty and the umbrella was still in the corner.', prompt:'What changed between 9:00 and 9:30?', options:[['The grey coat was no longer on the second hook.',true],['The umbrella was taken by the coat owner.',false],['The office door was locked at 9:30.',false]], explanation:'Only the coat is recorded as gone at 9:30. The umbrella is stated as still there, and nothing is said about the door being locked.', observation:'A grey coat on the second hook at 9:00; an empty hook and the same umbrella at 9:30.', inference:'The coat owner took the umbrella, or the door was locked.', alternative:'The coat may have been moved to another hook, or taken by its owner for the day.' },
    { id:'obs-white-van', track:'observation', title:'The white van', format:'Detail recall', difficulty:1, observe:'At 2:10, a white van stopped outside the shop. The driver carried a cardboard box to the side door. A bicycle was parked against the railing. A sign in the shop window read OPEN.', prompt:'Which detail was directly described?', options:[['The driver was in a hurry to finish the route.',false],['The van was delivering a secret package.',false],['A white van stopped outside the shop and the driver carried a cardboard box to the side door.',true]], explanation:'The van, box, and side door are stated directly. Hurry and secrecy are interpretations with no evidence in the scene.', observation:'A white van, cardboard box, side door, bicycle, railing, OPEN sign.', inference:'The driver was rushed, or the box held something secret.', alternative:'The box may hold ordinary stock; the driver may be on a routine delivery round.' },
    { id:'obs-library-return', track:'observation', title:'The returned book', format:'Observation note', difficulty:1, scenario:'At 4:15, Maya placed a hardcover book on the library return shelf. The book had a torn corner on the back cover. Maya said nothing and walked to the exit.', prompt:'Which note stays closest to what was observed?', options:[['Maya felt guilty about damaging the book.',false],['Maya placed a hardcover book with a torn back corner on the return shelf at 4:15.',true],['Maya damaged the book herself.',false]], explanation:'The time, the book, and the torn corner are observable. Guilt and responsibility for the damage are not shown by these facts alone.', observation:'A hardcover book, a torn back corner, the return shelf, 4:15, a silent walk to the exit.', inference:'Maya felt guilty, or caused the damage.', alternative:'The tear may predate Maya, or she may not have noticed it.' },
    { id:'obs-kitchen-timer', track:'observation', title:'The kitchen timer', format:'Observation vs. inference', difficulty:1, scenario:'At 7:00, the kitchen timer rang. Ravi turned off the oven, took out a tray, and set it on the stove. He did not speak.', prompt:'Which statement is an observation, not an inference?', options:[['Ravi turned off the oven and set a tray on the stove after the timer rang.',true],['Ravi was annoyed that dinner was late.',false],['Ravi had forgotten to set the timer earlier.',false]], explanation:'The timer, the oven, and the tray are actions that could be seen. Annoyance and forgetting are mental states that were not observed.', observation:'A timer rang at 7:00; Ravi turned off the oven and moved a tray to the stove.', inference:'Ravi was annoyed, or had forgotten the timer.', alternative:'Ravi may be following a recipe step, or working quietly by habit.' },
    { id:'obs-taxi-meter', track:'observation', title:'The taxi meter', format:'Timeline check', difficulty:2, scenario:'A taxi log shows a pickup at 6:12 and a drop-off at 6:38. A receipt for the same trip shows 6:38. A note from the driver says the trip took about 25 minutes.', prompt:'What is supported by the records?', options:[['The driver took a longer route on purpose.',false],['The trip must have started at 6:05.',false],['Pickup at 6:12 and drop-off at 6:38 match the receipt; the note gives an approximate duration.',true]], explanation:'The log and receipt agree on the end time, and the note is approximate. Nothing in the records shows route choice or a different start time.', observation:'A 6:12 pickup, a 6:38 drop-off, a matching receipt, and an approximate note.', inference:'The driver chose a longer route deliberately.', alternative:'Traffic, a detour, or a different pickup point could explain the duration.' },
    { id:'obs-shop-queue', track:'observation', title:'The shop queue', format:'Observation vs. inference', difficulty:2, scenario:'At 10:20, four people stood in a queue at the till. One person stepped out of the queue, checked a shelf, and returned to the same place. The cashier continued serving the person at the front.', prompt:'Which note stays within the evidence?', options:[['One person left the queue, checked a shelf, and returned to the same place at 10:20.',true],['The person who stepped out was trying to skip the queue.',false],['The cashier was ignoring the queue.',false]], explanation:'The movement and the return are observable. Skipping the queue and ignoring customers are motives that the facts do not establish.', observation:'Four people in a queue at 10:20; one stepped out, checked a shelf, and returned.', inference:'The person tried to skip ahead, or the cashier was ignoring the queue.', alternative:'The person may have forgotten an item, or checked a price before paying.' },
    { id:'obs-park-bench', track:'observation', title:'The park bench', format:'Detail recall', difficulty:2, observe:'At 5:05, a woman in a blue scarf sat on the middle bench in the park. A newspaper lay folded beside her. A dog on a lead walked past with its owner. A street lamp near the path was already on.', prompt:'Which detail was directly described?', options:[['The woman was waiting for someone to arrive.',false],['A woman in a blue scarf sat on the middle bench with a folded newspaper beside her.',true],['The dog owner was in a hurry.',false]], explanation:'The scarf, bench, and newspaper are stated in the scene. Waiting and hurry are interpretations, not details that were described.', observation:'A blue scarf, middle bench, folded newspaper, a dog on a lead, a lit street lamp.', inference:'The woman was waiting for someone, or the dog owner was hurrying.', alternative:'The woman may be resting or reading; the dog owner may be on a routine walk.' },
    { id:'obs-clinic-waiting', track:'observation', title:'The clinic waiting room', format:'Contradiction spotting', difficulty:2, scenario:'A sign-in sheet records Arjun arriving at 9:02. A second note says Arjun was called in at 9:10. A third note says the waiting room was empty at 9:05, with no mention of Arjun.', prompt:'What is the most careful reading?', options:[['Arjun must have signed in under a false name.',false],['The sign-in sheet is clearly wrong.',false],['The records differ in a way that needs checking; no single record alone settles where Arjun was at 9:05.',true]], explanation:'A difference between records is a question, not a conclusion. The empty-room note may be incomplete, and the other records may still be accurate.', observation:'A 9:02 sign-in, a 9:10 call-in, and a 9:05 note describing an empty room.', inference:'Arjun used a false name, or the sign-in sheet is wrong.', alternative:'The 9:05 note may have missed Arjun, or the times may be approximate.' },
    { id:'obs-storeroom-shelf', track:'observation', title:'The storeroom shelf', format:'Observation note', difficulty:2, scenario:'At 1:40, a count lists six boxes on the top shelf of the storeroom. At 2:05, a second count lists five boxes on the same shelf. Neither count records a removal, a delivery, or a recount.', prompt:'Which statement stays within the evidence?', options:[['The top shelf held six boxes at 1:40 and five boxes at 2:05; no removal was recorded.',true],['Someone stole a box between the counts.',false],['The first count was deliberately inflated.',false]], explanation:'Both counts can be recorded without adding a cause. Theft and deliberate inflation are serious claims that need evidence beyond a changed count.', observation:'Six boxes at 1:40 and five boxes at 2:05 on the top shelf, with no removal recorded.', inference:'A box was stolen, or the first count was inflated.', alternative:'A box may have been moved, miscounted, or taken for routine use.' },
    { id:'obs-school-corridor', track:'observation', title:'The school corridor', format:'Detail recall', difficulty:2, observe:'At 12:30, a trolley with three stacked chairs stood outside room 4 in the school corridor. A notice board beside the door listed two events. A fire extinguisher hung on the wall opposite. The corridor lights were on.', prompt:'Which detail was directly described?', options:[['The chairs were being moved to the hall for an assembly.',false],['A trolley with three stacked chairs stood outside room 4, beside a notice board listing two events.',true],['The fire extinguisher had been used recently.',false]], explanation:'The trolley, chairs, room number, and notice board are stated directly. An assembly and recent use of the extinguisher are not in the scene.', observation:'A trolley, three stacked chairs, room 4, a notice board with two events, a fire extinguisher.', inference:'The chairs were headed to an assembly, or the extinguisher had been used.', alternative:'The chairs may be stored there, or awaiting collection after a class.' },
    { id:'obs-reception-desk', track:'observation', title:'The reception desk', format:'Detail recall', difficulty:2, observe:'At 8:50, a visitor signed the guest book at the reception desk. A vase with white flowers stood at the left end of the desk. A telephone rang once and stopped. A calendar on the wall showed the 14th.', prompt:'Which detail was directly described?', options:[['The visitor was nervous about the meeting.',false],['The visitor was expected by the manager.',false],['A visitor signed the guest book at 8:50; a vase with white flowers stood at the left end of the desk.',true]], explanation:'The guest book, time, vase, and flowers are stated in the scene. Nervousness and an expected meeting are not observable from these details.', observation:'A signed guest book, 8:50, a vase with white flowers, one telephone ring, a calendar showing the 14th.', inference:'The visitor was nervous, or was expected by the manager.', alternative:'The visitor may be a regular caller, or the ring may have been a wrong number.' },
    { id:'obs-cafe-table', track:'observation', title:'The cafe table', format:'Observation vs. inference', difficulty:2, scenario:'At 3:45, two cups sat on a cafe table. One cup was empty; the other was half full. A coat hung over the back of one chair. No one was sitting at the table.', prompt:'Which note stays closest to observable facts?', options:[['Two cups sat on a cafe table; one was empty, one was half full, and a coat hung over a chair.',true],['The two customers left in a hurry after an argument.',false],['The coat owner will return within five minutes.',false]], explanation:'The cups, their levels, and the coat are observable. An argument, a hurry, and a return time are not shown by an empty table.', observation:'Two cups, one empty and one half full, a coat over a chair, no one seated.', inference:'The customers argued and left in a hurry, or will return soon.', alternative:'The customers may have finished, stepped away, or left the coat behind by mistake.' },
    { id:'obs-bus-stop', track:'observation', title:'The bus stop', format:'Timeline check', difficulty:2, scenario:'A timetable says the bus leaves at 7:15. A passenger note says the bus arrived at 7:18. A second passenger says they boarded at 7:20. No record states when the bus left.', prompt:'What can be concluded from these facts alone?', options:[['The bus was late because the driver stopped for coffee.',false],['The timetable, arrival note, and boarding note differ; the departure time is not established.',true],['The second passenger boarded the wrong bus.',false]], explanation:'The three times describe different events and do not agree on a departure. A reason for lateness and a wrong bus are not in the records.', observation:'A 7:15 timetable departure, a 7:18 arrival note, and a 7:20 boarding note.', inference:'The driver stopped for coffee, or the passenger took the wrong bus.', alternative:'The timetable may be scheduled rather than actual, and boarding may have taken a few minutes.' },
    { id:'obs-two-clocks', track:'observation', title:'Two clocks, two times', format:'Contradiction spotting', difficulty:3, scenario:'A wall clock in the office shows 10:42. A computer screen in the same room shows 10:37. A meeting log records a call starting at 10:40. No record states which clock was checked.', prompt:'What is the most careful next statement?', options:[['The meeting log must be wrong.',false],['The clocks disagree by five minutes; the call start time cannot be fixed from these records alone.',true],['Someone changed the wall clock to hide a late start.',false]], explanation:'Two clocks showing different times create uncertainty, not proof of error or tampering. The log may match one clock, and either clock may be unchecked.', observation:'A wall clock at 10:42, a computer at 10:37, and a log entry at 10:40.', inference:'The log is wrong, or the wall clock was changed deliberately.', alternative:'One clock may drift, a time zone may differ, or the log may use a third clock.' },
    { id:'obs-shift-handover', track:'observation', title:'The shift handover', format:'Contradiction spotting', difficulty:3, scenario:'The outgoing note says the front door was locked at 6:00. The incoming note says the front door was found unlocked at 6:05. Neither note records a key use, a visitor, or a check of the back door.', prompt:'What is the most careful conclusion?', options:[['The outgoing worker lied about locking the door.',false],['The incoming worker forgot to check the lock.',false],['The two notes conflict about the door; who acted, and when, is not established.',true]], explanation:'A conflict between notes identifies a gap to investigate. It does not establish dishonesty, forgetfulness, or any particular cause.', observation:'A 6:00 locked note and a 6:05 unlocked note, with no key or visitor record.', inference:'One worker lied, or the other failed to check.', alternative:'The lock may have failed, the door may have been opened briefly, or a note may be mistaken.' },
    { id:'obs-missing-key', track:'observation', title:'The missing key', format:'Evidence evaluation', difficulty:3, scenario:'A key hook holds four labelled keys at 8:00. At 9:00, the hook holds three keys, and the label for the storeroom key is empty. No sign-out sheet was used, and the room was open at 9:00.', prompt:'Which summary best matches the evidence?', options:[['The storeroom key is missing from its hook at 9:00; who took it, and why, is unknown.',true],['The key was stolen by the last person in the room.',false],['The key was lost because the hook system is useless.',false]], explanation:'The count and the empty label are facts. Theft, a named person, and a judgment about the system go beyond what the records show.', observation:'Four keys at 8:00; three keys and an empty storeroom label at 9:00; no sign-out sheet.', inference:'The key was stolen by a particular person, or the system is useless.', alternative:'The key may be in use, in a pocket, or placed on another hook.' },
    { id:'obs-delivery-log', track:'observation', title:'The delivery log', format:'Timeline check', difficulty:3, scenario:'A delivery log lists a parcel signed for at 11:20. A camera shows a courier at the door at 11:18, but the parcel is not visible in the frame. A second log lists the same parcel as collected at 11:25.', prompt:'What is supported right now?', options:[['The courier never delivered the parcel.',false],['The parcel was collected by someone else at 11:25.',false],['A courier was seen at 11:18 and a signature is logged at 11:20; whether the parcel in the frame is the same one is not shown.',true]], explanation:'Each record supports only its own event. The camera angle leaves the parcel unseen, so the records cannot be merged into one certain story.', observation:'A courier at 11:18, a signature at 11:20, and a collection entry at 11:25.', inference:'No delivery happened, or another person collected the parcel.', alternative:'The parcel may be out of frame, or the logs may use different clocks.' },
    { id:'obs-meeting-notes', track:'observation', title:'The meeting notes', format:'Observation note', difficulty:3, scenario:'Two people took notes at the same meeting. One note says the budget was approved. The other note says the budget was discussed and a decision was deferred. Neither note quotes the exact words used.', prompt:'What is the fairest next step?', options:[['Trust the first note because it is more confident.',false],['Compare both notes with the meeting record or ask the chair to confirm what was decided, before acting on either.',true],['Assume the second note-taker was not paying attention.',false]], explanation:'Confidence is not accuracy. When notes conflict and neither quotes the decision, an independent record or a neutral confirmation is needed.', observation:'Two notes conflict on approval versus deferral; neither quotes exact words.', inference:'One note-taker was confident and right, or the other was inattentive.', alternative:'Either note may be mistaken; the chair may have used wording that allowed both readings.' },
    { id:'obs-lost-umbrella-report', track:'observation', title:'The lost umbrella report', format:'Contradiction spotting', difficulty:3, scenario:'A visitor reports losing a black umbrella in the lobby at 2:00. A staff log says a black umbrella was found in the meeting room at 2:30. No record describes the umbrella in detail, and no one saw it move.', prompt:'What is the most careful statement?', options:[['The two reports may describe the same umbrella, but without a detailed description that cannot be established.',true],['The visitor is mistaken about the time.',false],['The staff log must have the wrong room.',false]], explanation:'Two reports mention a black umbrella at different times and places, but without a detailed description they cannot be linked with certainty.', observation:'A lost black umbrella reported at 2:00 in the lobby; a found black umbrella logged at 2:30 in the meeting room.', inference:'The visitor misremembered, or the log has the wrong room.', alternative:'Two different black umbrellas may be involved, or the umbrella may have been moved.' },
    { id:'obs-storeroom-count', track:'observation', title:'The storeroom count', format:'Evidence evaluation', difficulty:3, scenario:'A morning count records twelve tins on a shelf. An evening count records nine tins on the same shelf. The issue log shows two tins issued during the day. No other record mentions the shelf.', prompt:'Which summary best matches the evidence?', options:[['One tin is unaccounted for by the records; the cause is not established.',true],['One tin was taken without permission.',false],['The morning count was correct and the evening count was wrong.',false]], explanation:'Twelve tins minus two issued leaves ten expected, but nine were counted. That one-tin gap is a fact; its cause is not established by the records.', observation:'Twelve tins in the morning, nine in the evening, and two issued in the log.', inference:'A tin was taken without permission, or one count was wrong.', alternative:'A tin may have been moved, miscounted, or issued without a log entry.' },
    { id:'obs-phone-log', track:'observation', title:'The phone log', format:'Timeline check', difficulty:3, scenario:'A phone log shows a call at 4:12 lasting three minutes. A witness says they spoke to the same person at about 4:15. A second log shows a different number called at 4:14.', prompt:'What is supported right now?', options:[['The witness is lying about the call.',false],['The logs and the approximate witness time overlap, but they do not prove a single call or identify the number used.',true],['The second log proves the first call never happened.',false]], explanation:'An approximate time can overlap with a logged call without proving it is the same call. The second log is a separate event, not proof against the first.', observation:'A 4:12 call lasting three minutes, an approximate 4:15 account, and a different number at 4:14.', inference:'The witness lied, or the second log disproves the first call.', alternative:'The witness may be recalling the same call approximately, or a different call entirely.' },
    { id:'obs-door-code', track:'observation', title:'The door code', format:'Contradiction spotting', difficulty:3, scenario:'A notice says the side door code changed on Monday. A staff member says they used the old code on Wednesday and it worked. A second staff member says the new code worked on Wednesday. No record shows when the code was actually changed.', prompt:'What is the most careful conclusion?', options:[['The first staff member is making up the story.',false],['The second staff member must be mistaken.',false],['The accounts conflict and the change date is unverified; neither account alone settles what code worked on Wednesday.',true]], explanation:'Two conflicting accounts plus an unverified change date leave the facts open. Either account could be mistaken, or the change may have happened later than the notice.', observation:'A Monday change notice and two conflicting Wednesday accounts, with no change record.', inference:'One staff member invented a story, or the other is mistaken.', alternative:'The code change may have been delayed, or both codes may have worked during a transition.' },
    { id:'psych-availability-news', track:'psychology', title:'A vivid story, a rare risk', format:'Alternative explanations', difficulty:1, scenario:'After a news report about a break-in at a shop across town, Priya worries that her own shop is likely to be broken into tonight, even though local records show no recent break-ins nearby.', prompt:'What is the most careful way to judge the risk?', options:[['Recent news can make an event feel more common, so check local records before judging the risk.',true],['The news report proves her shop is at high risk tonight.',false],['A vivid story is a better guide than local records.',false]], explanation:'Availability makes recent or vivid examples feel more frequent than they are. Local records give a steadier base for the judgment.', observation:'A news report about a distant break-in, and no recent local break-ins in the records.', inference:'Her shop is likely to be targeted tonight.', alternative:'The risk may be low locally, and the news story may reflect one distant event rather than a local pattern.' },
    { id:'psych-halo-helpful', track:'psychology', title:'Friendly is not the same as sound', format:'Context check', difficulty:1, scenario:'At a school fair, a volunteer who is friendly and well dressed suggests a new way to count raffle tickets. Several parents accept the idea without checking the counting steps.', prompt:'What is the fairest way to judge the suggestion?', options:[['A friendly person must have a sound plan.',false],['Judge the counting steps on their own merits, separate from how friendly the volunteer seems.',true],['A good first impression proves the plan will work.',false]], explanation:'Halo effect lets one positive trait colour a separate judgment. The steps need checking on their own.', observation:'A friendly volunteer suggested a new counting method at a school fair.', inference:'The method is sound because the volunteer seems pleasant.', alternative:'The method may have a flaw, or it may work well once the steps are tested.' },
    { id:'psych-attribution-late', track:'psychology', title:'Late once, judged always', format:'Alternative explanations', difficulty:1, scenario:'Ravi arrives ten minutes late to a team meeting on Tuesday after his bus was delayed by road work. A colleague says Ravi does not care about the team.', prompt:'What is the most responsible interpretation?', options:[['Being late once proves a lack of care.',false],['The delay shows Ravi planned to arrive late.',false],['One late arrival has many possible causes, and the bus delay is a stated situational factor.',true]], explanation:'Fundamental attribution error favours a personal trait over the situation. Check the context before judging character.', observation:'Ravi arrived ten minutes late after a bus delay caused by road work.', inference:'Ravi does not care about the team.', alternative:'Traffic, a late bus, or a family matter could explain the delay on that day.' },
    { id:'psych-anchor-price', track:'psychology', title:'The first price sets the mood', format:'Anchoring check', difficulty:1, scenario:'A shop lists a used bicycle at 420 dollars, then offers it for 300 dollars. Omar thinks 300 dollars is a bargain mainly because the first price was higher.', prompt:'What is the most careful way to judge the price?', options:[['Compare 300 dollars with prices for similar bicycles, not only with the first listed price.',true],['The first price proves 300 dollars is a good deal.',false],['A large discount always means fair value.',false]], explanation:'Anchoring lets the first number shape the judgment. Independent comparisons give a better check.', observation:'A bicycle was listed at 420 dollars and then offered at 300 dollars.', inference:'The lower price must be a bargain.', alternative:'Similar bicycles may sell for less, or the first price may have been set high on purpose.' },
    { id:'psych-base-rate-rare', track:'psychology', title:'Rare faults and loud tests', format:'Base rates', difficulty:1, scenario:'A rare fault affects 1 in 500 printers. A quick test flags a printer, but the test also flags many healthy printers. Sam assumes the flagged printer almost certainly has the fault.', prompt:'What is the most careful conclusion?', options:[['A positive test result always means the fault is present.',false],['Because the fault is rare and the test flags healthy printers, the chance is lower than it first seems.',true],['The base rate does not matter once a test flags a printer.',false]], explanation:'Base rates matter when a condition is rare. A test result must be weighed against how often the fault occurs.', observation:'The fault affects 1 in 500 printers, and the test flags many healthy printers.', inference:'A flagged printer almost certainly has the fault.', alternative:'The printer may be healthy, and a second independent check could clarify the result.' },
    { id:'psych-cue-tired', track:'psychology', title:'Yawns are not verdicts', format:'Alternative explanations', difficulty:1, scenario:'During a morning class, Ana yawns twice and looks out the window while the teacher explains a schedule change.', prompt:'What is the fairest first interpretation?', options:[['Yawning proves Ana is bored and rude.',false],['Looking away proves Ana is ignoring the teacher.',false],['Those are observations; tiredness, a poor night of sleep, or a distraction could explain them.',true]], explanation:'A single cue has many possible causes. Do not treat yawning or a glance as proof of attitude or intent.', observation:'Ana yawned twice and looked out the window during a schedule explanation.', inference:'Ana is bored, rude, or ignoring the teacher.', alternative:'Ana may be tired, unwell, or briefly distracted by something outside.' },
    { id:'psych-context-culture', track:'psychology', title:'Soft speech, different norms', format:'Context check', difficulty:1, scenario:'In a meeting with colleagues from different backgrounds, Kenji speaks softly, pauses often, and avoids direct eye contact while giving a careful answer.', prompt:'What is the most careful interpretation?', options:[['Speaking style varies with culture, personality, and context, so it does not prove uncertainty or evasion.',true],['Soft speech proves Kenji is unsure of the answer.',false],['Avoiding eye contact proves Kenji is hiding something.',false]], explanation:'Communication norms differ across cultures and people. Style alone cannot establish meaning or intent.', observation:'Kenji spoke softly, paused, and avoided direct eye contact while answering carefully.', inference:'Kenji is uncertain or evasive.', alternative:'Kenji may be showing respect, thinking carefully, or following a different communication norm.' },
    { id:'psych-change-mind', track:'psychology', title:'What would change your mind', format:'Bias check', difficulty:1, scenario:'You believe a new rota will reduce late starts at a cafe. After one week, late starts fall by one, but two staff members report longer closing times.', prompt:'What question best tests your belief?', options:[['Only collect stories that praise the new rota.',false],['Ask what evidence would change your mind, then check late starts and closing times together.',true],['One small improvement proves the rota is a success.',false]], explanation:'Asking what would change your mind invites a fair test. A single result does not settle a claim with mixed effects.', observation:'Late starts fell by one, and two staff members reported longer closing times.', inference:'The new rota is clearly a success.', alternative:'The rota may help starts but hurt closing, or the change may be too small to judge yet.' },
    { id:'psych-confirmation-review', track:'psychology', title:'One invoice is not the case', format:'Bias check', difficulty:2, scenario:'You suspect a supplier sent the wrong parts. You find one invoice that seems to support the idea, then stop looking at other invoices or delivery notes.', prompt:'What is the best next step?', options:[['Keep only the invoice that supports the suspicion.',false],['Treat one invoice as proof of a supplier mistake.',false],['Check other invoices and delivery notes, including records that could show the parts were correct.',true]], explanation:'Confirmation bias stops the search at the first match. Disconfirming records are needed to test the suspicion fairly.', observation:'One invoice seems to support the suspicion about wrong parts.', inference:'The supplier definitely sent the wrong parts.', alternative:'A filing error, a partial delivery, or a correct shipment with a confusing invoice could explain the record.' },
    { id:'psych-hindsight-project', track:'psychology', title:'Obvious only after the fact', format:'Hindsight check', difficulty:2, scenario:'After a community event runs over budget, several organisers say the overspend was obvious from the start, though none of them raised it in the planning meetings.', prompt:'What is the most careful view?', options:[['Knowing the outcome can make it feel predictable, so check what was actually known and said before the event.',true],['The overspend was clearly obvious to everyone at the time.',false],['People who claim hindsight must have warned the group earlier.',false]], explanation:'Hindsight bias makes a known outcome feel inevitable. Planning notes show what was known before the result.', observation:'The event ran over budget, and organisers now say the overspend was obvious.', inference:'Everyone knew the overspend would happen.', alternative:'Costs may have risen from an unexpected price change, or the warning may have been unclear at the time.' },
    { id:'psych-availability-flight', track:'psychology', title:'Two stories versus the data', format:'Alternative explanations', difficulty:2, scenario:'After two friends describe turbulent flights, Daniel decides flying is very dangerous and plans a long drive instead, though safety data show driving the same distance carries higher risk.', prompt:'What is the most careful way to judge the risk?', options:[['Vivid stories from friends prove flying is very dangerous.',false],['Compare the safety data for both options, because vivid stories can make a rare event feel common.',true],['Personal stories should replace safety data in this decision.',false]], explanation:'Availability makes memorable stories feel representative. Comparative data give a steadier basis for a risk choice.', observation:'Two friends described turbulent flights, and safety data favour flying over driving the same distance.', inference:'Flying is very dangerous.', alternative:'The flights may have been unusual, and the drive may carry its own higher risk.' },
    { id:'psych-anchor-salary', track:'psychology', title:'The first salary number', format:'Anchoring check', difficulty:2, scenario:'A job posting lists a salary range starting at 52000 dollars. During talks, Maya keeps judging every offer against 52000 dollars, even though similar roles in the same town pay 44000 to 48000 dollars.', prompt:'What is the most careful next step?', options:[['The first number in the posting must be the fair rate.',false],['Any offer below 52000 dollars is unfair by definition.',false],['Check pay for similar roles in the same town before judging an offer against the first number.',true]], explanation:'Anchoring lets an early number set the standard. Local pay for similar work is a better reference point.', observation:'A posting lists 52000 dollars, while similar local roles pay 44000 to 48000 dollars.', inference:'52000 dollars is the fair rate for the role.', alternative:'The posting range may be broad, or local roles may differ in duties and hours.' },
    { id:'psych-halo-presentation', track:'psychology', title:'A smooth talk, an untested system', format:'Context check', difficulty:2, scenario:'A confident speaker gives a smooth presentation about a new filing system, with clear slides and strong eye contact. The audience rates the system highly before testing it.', prompt:'What is the fairest way to judge the system?', options:[['Test the filing system with real files and timing, separate from how smooth the presentation was.',true],['A confident presentation proves the system works well.',false],['Clear slides mean the system has no flaws.',false]], explanation:'Halo effect lets presentation skill colour a judgment about the system itself. A practical test separates the two.', observation:'A confident speaker gave a smooth presentation with clear slides about a new filing system.', inference:'The filing system must work well.', alternative:'The system may be slow in daily use, or it may work well once staff try it with real files.' },
    { id:'psych-attribution-mistake', track:'psychology', title:'A new till, a long queue', format:'Alternative explanations', difficulty:2, scenario:'A new cashier makes an error on a till at a busy market stall on Saturday. A supervisor says the cashier is careless, though the till was new, the queue was long, and no training session had been held.', prompt:'What is the most responsible interpretation?', options:[['One error proves the cashier is careless.',false],['The new till, long queue, and lack of training are situational factors that could explain the error.',true],['A busy day cannot affect accuracy.',false]], explanation:'Fundamental attribution error overlooks situational pressure. Training, tools, and workload matter before judging a person.', observation:'A new cashier made a till error on a busy Saturday with a new till and no training session.', inference:'The cashier is careless.', alternative:'The error may come from unfamiliar equipment, time pressure, or unclear instructions.' },
    { id:'psych-base-rate-test', track:'psychology', title:'A rare condition, a loud test', format:'Base rates', difficulty:2, scenario:'A screening test for a rare condition affects 1 in 1000 people. The test correctly finds most cases but also flags 50 healthy people out of every 1000 tested. A flagged result arrives for a person with no symptoms.', prompt:'What is the most careful conclusion?', options:[['A flagged result means the person almost certainly has the condition.',false],['The test result alone proves the diagnosis.',false],['Because the condition is rare and false flags are common, the result needs a second independent test before a conclusion.',true]], explanation:'Base rates change what a positive result means. With a rare condition and many false flags, one test is not enough.', observation:'The condition affects 1 in 1000 people, the test flags 50 healthy people per 1000, and the person has no symptoms.', inference:'The flagged person almost certainly has the condition.', alternative:'The person may be healthy, and a second test could give a clearer result.' },
    { id:'psych-memory-stress', track:'psychology', title:'Stress scrambles the order', format:'Memory and stress', difficulty:2, scenario:'After a stressful fire drill at a school, two teachers recall the order of events differently. One says the alarm sounded before the announcement, the other says the announcement came first.', prompt:'What is the fairest next move?', options:[['Treat both accounts as possibly affected by stress, and check the alarm log and announcement record.',true],['The more confident teacher must be remembering correctly.',false],['Stress proves one teacher is lying.',false]], explanation:'Stress can affect memory for order and detail. Records help separate what happened from how it was remembered.', observation:'Two teachers disagree about whether the alarm or the announcement came first after a stressful drill.', inference:'One teacher is lying or has a perfect memory.', alternative:'Either teacher could be mistaken about order, and the logs may show a clear sequence.' },
    { id:'psych-framing-risk', track:'psychology', title:'Same numbers, different frame', format:'Framing check', difficulty:2, scenario:'A clinic notice says a treatment helps 90 in 100 people. A second notice says the same treatment does not help 10 in 100 people. A patient feels much more confident after reading the first notice.', prompt:'What is the most careful way to judge the treatment?', options:[['The first wording proves the treatment is safer.',false],['Both wordings describe the same result, so judge the numbers, not the framing.',true],['A positive frame means the risk is lower.',false]], explanation:'Framing changes how the same numbers feel. The underlying rates are identical, so the decision should rest on them.', observation:'One notice says 90 in 100 are helped, the other says 10 in 100 are not helped.', inference:'The first wording shows a safer treatment.', alternative:'The patient may still need details about side effects, cost, and other options.' },
    { id:'psych-calibration-strong', track:'psychology', title:'Strong on time, silent on signer', format:'Confidence calibration', difficulty:3, scenario:'Three independent records support a delivery time, but none of them records who signed for the package, and a fourth note has a smudged time.', prompt:'Which summary best matches the evidence?', options:[['The delivery time is well supported, while the signer and the smudged note remain unresolved.',true],['The delivery time proves who signed for the package.',false],['One smudged note means none of the records can be trusted.',false]], explanation:'Confidence can differ by question. Support for time does not transfer to identity, and one unclear record does not erase the others.', observation:'Three records support a delivery time, none names the signer, and a fourth note has a smudged time.', inference:'The time proves who signed for the package.', alternative:'The signer may be identified by another record, or the smudged note may be clarified by its author.' },
    { id:'psych-confirmation-strong', track:'psychology', title:'Three good weeks, two bad weeks', format:'Bias check', difficulty:3, scenario:'A manager believes a new shift pattern caused fewer errors. She finds three weeks where errors fell, but ignores two weeks where errors rose and does not check whether workload also changed.', prompt:'What is the best next reasoning move?', options:[['Three supportive weeks prove the shift pattern caused the fall.',false],['Compare all weeks, check workload and other changes, and ask what result would weaken the belief.',true],['Ignoring the rising weeks makes the conclusion stronger.',false]], explanation:'Selective evidence can create a false pattern. Full data and a stated disconfirming test give a fairer check.', observation:'Errors fell in three weeks and rose in two weeks, while workload was not checked.', inference:'The shift pattern caused fewer errors.', alternative:'Workload, staffing, or a seasonal change could explain the pattern.' },
    { id:'psych-base-rate-strong', track:'psychology', title:'A rare allergy, a common flag', format:'Base rates', difficulty:3, scenario:'A rare allergy affects 1 in 2000 children. A new screening flags 1 in 100 children, mostly healthy children, and a flagged child has no symptoms and no family history.', prompt:'What is the most careful conclusion?', options:[['A flagged result proves the child has the allergy.',false],['The screening result alone settles the diagnosis.',false],['Given the low base rate and many false flags, the result is weak evidence and needs a confirmatory test.',true]], explanation:'A rare base rate plus a high false flag rate makes one positive result weak. A confirmatory test is needed before acting on it.', observation:'The allergy affects 1 in 2000 children, the screening flags 1 in 100, and the child has no symptoms or family history.', inference:'The flagged child has the allergy.', alternative:'The child is likely healthy, and a second test could confirm or rule out the allergy.' },
    { id:'psych-hindsight-strong', track:'psychology', title:'Inevitable only in hindsight', format:'Hindsight check', difficulty:3, scenario:'After a local shop closes, residents say the closure was inevitable because foot traffic had fallen for a year. Before the closure, the same residents had signed a petition saying the shop would recover.', prompt:'What is the most careful view?', options:[['Knowing the outcome can rewrite earlier expectations, so check what people actually said and knew before the closure.',true],['The closure was obviously inevitable all along.',false],['The earlier petition proves residents were lying at the time.',false]], explanation:'Hindsight bias can make a past outcome feel predictable. Earlier records show what was expected before the result was known.', observation:'Residents now call the closure inevitable, but earlier they signed a petition saying the shop would recover.', inference:'Everyone knew the shop would close.', alternative:'A sudden rent rise or a new competitor may have changed the outlook after the petition.' },
    { id:'psych-attribution-strong', track:'psychology', title:'A missed turn in the rain', format:'Alternative explanations', difficulty:3, scenario:'A driver misses a turn on a route she has driven for years. A passenger says she is a bad driver, though she was following a new detour sign, the road markings were faded, and it was raining.', prompt:'What is the most responsible interpretation?', options:[['One missed turn proves the driver is bad.',false],['The detour sign, faded markings, and rain are situational factors that could explain the missed turn.',true],['Experience means a driver cannot be affected by road conditions.',false]], explanation:'Fundamental attribution error favours a trait over the situation. Road conditions and new signs matter before judging skill.', observation:'An experienced driver missed a turn while following a detour sign in rain with faded markings.', inference:'The driver is a bad driver.', alternative:'The detour may have been unclear, or the markings may have misled any driver in the same rain.' },
    { id:'psych-context-strong', track:'psychology', title:'Short answers in a new country', format:'Context check', difficulty:3, scenario:'In a workplace in a new country, a colleague gives short answers, avoids small talk, and leaves meetings promptly at the end time. A teammate reads this as coldness, though the colleague is new, is working in a second language, and has a strict childcare pickup time.', prompt:'What is the fairest interpretation?', options:[['Short answers prove the colleague is cold.',false],['Leaving promptly proves the colleague dislikes the team.',false],['Language, a new setting, and a fixed pickup time offer plausible context, so the behaviour does not prove coldness.',true]], explanation:'Context and culture shape behaviour. A fixed commitment and a second language can explain short answers without a character judgment.', observation:'A new colleague gives short answers, avoids small talk, and leaves promptly, with a second language and a childcare pickup time.', inference:'The colleague is cold or dislikes the team.', alternative:'The colleague may be focused, tired, or saving conversation for a better time.' },
    { id:'psych-memory-strong', track:'psychology', title:'Sure about colour, unsure about time', format:'Memory and stress', difficulty:3, scenario:'A witness recalls a car colour clearly after a stressful road incident, but is unsure about the plate number and the exact time. A second witness recalls the time clearly but is unsure about the colour.', prompt:'What is the most careful way to use these accounts?', options:[['Treat each detail separately, because memory can be strong for one detail and weak for another, and check both against records.',true],['The confident detail in each account proves the whole account is accurate.',false],['Uncertainty about one detail means the witness is lying.',false]], explanation:'Memory is not all or nothing. Confidence varies by detail, and records can test each claim on its own.', observation:'One witness is sure about colour but unsure about plate and time, the other is sure about time but unsure about colour.', inference:'A confident detail proves the whole memory is accurate.', alternative:'Either witness could be mistaken on a detail, and a camera or log may resolve the difference.' },
    { id:'psych-anchor-strong', track:'psychology', title:'A high quote makes a high price feel fair', format:'Anchoring check', difficulty:3, scenario:'A contractor quotes 9000 dollars for a repair, then offers 7000 dollars as a special price. The owner feels 7000 dollars is fair mainly because of the first quote, though two other contractors quoted 5200 and 5600 dollars for the same work.', prompt:'What is the most careful way to judge the price?', options:[['The first quote proves 7000 dollars is fair.',false],['Compare 7000 dollars with the other quotes and the scope of work, not only with the first quote.',true],['A discount from the first quote always means good value.',false]], explanation:'Anchoring lets the first quote set the standard. Independent quotes for the same work give a better reference point.', observation:'One contractor quoted 9000 then 7000 dollars, while two others quoted 5200 and 5600 dollars for the same work.', inference:'7000 dollars must be fair because it is lower than 9000 dollars.', alternative:'The scope may differ, or the first quote may have been set high to make the discount look large.' },
    { id:'psych-availability-strong', track:'psychology', title:'One story, a different park', format:'Alternative explanations', difficulty:3, scenario:'After a neighbour describes a rare dog bite in the park, several parents stop letting children play there, though park records show no bites in five years and the incident happened in a different park.', prompt:'What is the most careful way to judge the risk?', options:[['One vivid story proves the park is dangerous.',false],['Parents should act on the story alone without checking records.',false],['Check the park records and the location of the incident, because a vivid story can make a rare event feel common.',true]], explanation:'Availability makes a memorable story feel representative. Records and location give a steadier basis for judging risk.', observation:'A neighbour described a rare dog bite in a different park, while local park records show no bites in five years.', inference:'The local park is dangerous.', alternative:'The risk may be low locally, and the story may reflect a different place and time.' },
    { id:'crime-log-gap', track:'criminology', title:'The missing quarter hour', format:'Timeline analysis', difficulty:1, scenario:'A storeroom log records a check at 2:10 and the next check at 2:25. A box is found moved at 2:25. Nothing in the log describes the minutes between the two checks.', prompt:'What can be concluded from these facts alone?', options:[['The box was moved at 2:10, when the first check was made.',false],['The box was found moved at 2:25; when it was moved during the gap is not established.',true],['The person who made the 2:10 check moved the box.',false]], explanation:'The log gives two time points and a gap between them. A gap marks missing information, not an event time or a person.', observation:'Checks at 2:10 and 2:25; a box found moved at 2:25.', inference:'A named checker moved the box at a specific time.', alternative:'The box may have been moved at any point in the gap, or before the first check was fully recorded.' },
    { id:'crime-receipt-time', track:'criminology', title:'A receipt and a time', format:'Evidence evaluation', difficulty:1, scenario:'A library receipt shows a book was returned at 4:32. A sign-in sheet shows a visitor named Priya entered the building at 4:20. The receipt does not name who returned the book.', prompt:'What does the receipt support?', options:[['The receipt shows a book was returned at 4:32.',true],['The receipt proves Priya returned the book.',false],['The receipt proves Priya was in the library at 4:32.',false]], explanation:'A receipt supports the transaction and time it records. It does not identify the person who made the return.', observation:'A return receipt at 4:32 and a separate sign-in at 4:20.', inference:'Priya returned the book.', alternative:'Another visitor may have returned the book, or Priya may have left before 4:32.' },
    { id:'crime-secondhand-name', track:'criminology', title:'A name passed along', format:'Source evaluation', difficulty:1, scenario:'A receptionist says a coworker told her that a man named Arjun was near the delivery bay at noon. The receptionist did not see Arjun there herself, and the coworker has not been asked about it.', prompt:'What is the status of the claim about Arjun?', options:[['Arjun was near the delivery bay at noon.',false],['The claim is unconfirmed until the coworker is asked directly.',false],['It is a second-hand report; Arjun being there is not established.',true]], explanation:'A second-hand report is a lead to check, not a finding. The direct source still needs to be asked.', observation:'A receptionist repeats a coworker account about Arjun at noon.', inference:'Arjun was at the delivery bay.', alternative:'The coworker may have seen someone else, misremembered the time, or been misunderstood.' },
    { id:'crime-camera-angle', track:'criminology', title:'What the camera does not show', format:'Corroboration check', difficulty:1, scenario:'A camera in an office lobby shows the front entrance from 9:00 to 9:30. A supply shelf in a back room is found empty at 9:30. The camera view does not include the back room or the shelf.', prompt:'What can the camera footage establish?', options:[['The camera shows the entrance during that period; it says nothing about the back room shelf.',true],['The camera shows who entered the building between 9:00 and 9:30.',false],['The camera proves no one took anything from the shelf.',false]], explanation:'A record only supports what it actually covers. An empty shelf outside the camera view is not explained by the footage.', observation:'Entrance footage from 9:00 to 9:30; an empty shelf found at 9:30.', inference:'The footage identifies who emptied the shelf.', alternative:'The shelf may have been emptied before 9:00, after 9:30, or by someone who never crossed the entrance view.' },
    { id:'crime-note-approx', track:'criminology', title:'Around nine in the morning', format:'Timeline analysis', difficulty:1, scenario:'A handwritten note says a parcel was left at reception in the morning. A sign-in log records a courier arrival at 9:47. The note gives no exact time and no courier name.', prompt:'What is supported right now?', options:[['The note and the log together prove the parcel arrived at 9:47.',false],['The note gives an approximate time and the log records 9:47; the link between them is not established.',true],['The note proves the courier left the parcel.',false]], explanation:'An approximate note and a precise log are different kinds of evidence. They do not confirm each other without a link.', observation:'A note says morning; a log records a courier at 9:47.', inference:'The 9:47 courier left the parcel.', alternative:'The parcel may have arrived earlier, or a different courier may have left it.' },
    { id:'crime-two-clocks', track:'criminology', title:'Two clocks, one report', format:'Source evaluation', difficulty:1, scenario:'A wall clock in a meeting room shows 11:05 when a phone is reported missing. A computer log records a door opening at 11:02. No one has checked whether the wall clock and the computer use the same time.', prompt:'What is the careful reading?', options:[['The wall clock is wrong and the computer is right.',false],['The door opened three minutes before the phone was reported missing.',false],['The two times come from unchecked clocks, so their exact difference is not established.',true]], explanation:'Times from different devices cannot be compared precisely until their clocks are checked. A difference may be real or only a clock offset.', observation:'A wall clock shows 11:05; a computer log shows 11:02.', inference:'The door event happened three minutes earlier.', alternative:'Either clock may be fast or slow; checking both against a common time can clarify the order.' },
    { id:'crime-missing-page', track:'criminology', title:'A page is missing', format:'Gap in the record', difficulty:1, scenario:'A visitor sign-out sheet for Tuesday has pages for the morning and the afternoon, but the page covering 1:00 to 2:00 is missing. A visitor is recorded signing in at 12:40 and no sign-out time is visible.', prompt:'What does the missing page mean?', options:[['The visitor left between 1:00 and 2:00.',false],['The sign-out time is unknown because the covering page is missing.',true],['The visitor never signed out on purpose.',false]], explanation:'A missing page is a gap in the record. It does not show when a person left or why the page is absent.', observation:'A sign-in at 12:40; the 1:00 to 2:00 sign-out page is missing.', inference:'The visitor left in that hour deliberately.', alternative:'The page may have been misfiled, removed for copying, or lost for an ordinary reason.' },
    { id:'crime-delivery-signature', track:'criminology', title:'An unreadable signature', format:'Evidence evaluation', difficulty:1, scenario:'A delivery form confirms a box arrived at a school office at 10:15. The signature on the form is unreadable, and no printed name was added. The box is later found in the wrong room.', prompt:'What can the form establish?', options:[['The form shows a delivery at 10:15; the receiver is not identified.',true],['The form proves who moved the box to the wrong room.',false],['The form proves who received the box.',false]], explanation:'A delivery record supports the time and place it records. An unreadable signature cannot identify a person.', observation:'A delivery at 10:15 with an unreadable signature; a box later in the wrong room.', inference:'The signer moved the box.', alternative:'The box may have been moved later by someone else, or delivered to the wrong room by mistake.' },
    { id:'crime-conflicting-times', track:'criminology', title:'Ten minutes apart', format:'Timeline analysis', difficulty:2, scenario:'Two witnesses describe the same event in a park. Maya says a bench was empty at 3:00. Daniel says he saw a bag on the same bench at 3:10. Neither witness checked a clock at the time, and both gave their accounts the next day.', prompt:'What is the best next step?', options:[['Treat Maya as correct because she spoke first.',false],['Treat Daniel as correct because his time is more precise.',false],['Record both accounts with their limits, then look for a time-stamped record that can place the bag.',true]], explanation:'Two honest accounts can differ on time, especially when recalled a day later without a clock check. An independent time-stamped record can help sort the order.', observation:'Maya recalls an empty bench at 3:00; Daniel recalls a bag at 3:10.', inference:'One witness is lying about the bench.', alternative:'Either time may be approximate; the bag may have been placed, removed, or overlooked between the two observations.' },
    { id:'crime-partial-footage', track:'criminology', title:'Forty seconds missing', format:'Evidence evaluation', difficulty:2, scenario:'A camera covering a hallway records a person entering at 6:12 and the same hallway empty at 6:14. The recording has a forty-second gap in the middle, and the camera does not cover the side rooms off the hallway.', prompt:'What can the footage support?', options:[['The footage proves the person stayed in the hallway the whole time.',false],['The person must have entered a side room during the gap.',false],['The footage shows entry and a later empty hallway; the gap and side rooms leave the middle unknown.',true]], explanation:'Partial footage supports the segments it contains. A gap plus uncovered rooms means the middle of the sequence is not shown.', observation:'Entry at 6:12, empty hallway at 6:14, a forty-second gap, side rooms uncovered.', inference:'The person entered a side room.', alternative:'The person may have left the frame, waited out of view, or passed through during the gap.' },
    { id:'crime-copied-email', track:'criminology', title:'A forwarded email', format:'Evidence provenance', difficulty:2, scenario:'A case file holds a forwarded email that describes a meeting at 2:00. The original email is not in the file, the forwarding chain has no timestamps for the original send, and the sender of the forward was not at the meeting.', prompt:'What limits this email as evidence?', options:[['The forwarded copy proves the meeting happened at 2:00.',false],['Its origin and original timing cannot be checked from the forward alone, so it needs the original or another record.',true],['A forwarded email is always false.',false]], explanation:'A copy can lose the details that let a reader check it. Without the original or corroboration, its timing and wording remain uncertain.', observation:'A forwarded email about a 2:00 meeting; no original or original timestamps.', inference:'The meeting time is confirmed.', alternative:'The forward may have altered wording, or the meeting time may have been approximate in the original.' },
    { id:'crime-chain-custody', track:'criminology', title:'The key box handover', format:'Chain of custody', difficulty:2, scenario:'A key box log shows keys were signed out at 8:00 and signed back in at 5:00. The log has no entry for a midday handover mentioned by two staff members, and the box was left unlocked for part of the afternoon.', prompt:'What is the fairest conclusion about the keys?', options:[['The log supports sign-out and sign-in times; the undocumented handover leaves who held them midday unclear.',true],['The log proves the same person held the keys all day.',false],['The unlocked box proves the keys were used without permission.',false]], explanation:'A log supports the entries it contains. An undocumented handover and an unlocked period are gaps, not proof of misuse.', observation:'Sign-out at 8:00, sign-in at 5:00, an unlogged midday handover, an unlocked period.', inference:'The keys were misused.', alternative:'The handover may have been routine and simply unrecorded, and the unlocked period may have had no access.' },
    { id:'crime-independent-check', track:'criminology', title:'Two records, one date', format:'Corroboration check', difficulty:2, scenario:'A till receipt and a staff rota both place a transaction on Friday, but neither record names the person at the till. A third note names a staff member, but that note was written from memory a week later.', prompt:'What is corroborated here?', options:[['The date of the transaction is supported by two records; the person at the till is not.',true],['All three records together prove who was at the till.',false],['The later note cancels the receipt and the rota.',false]], explanation:'Corroboration is specific: records can agree on a date while still leaving identity open. A later memory note adds a claim, not proof.', observation:'A receipt and a rota agree on Friday; a later note names a person.', inference:'The named staff member was at the till.', alternative:'Another staff member may have covered the till, or the later note may misremember who was there.' },
    { id:'crime-timezone-call', track:'criminology', title:'A call across time zones', format:'Source evaluation', difficulty:2, scenario:'A phone log shows a call at 18:20, but the log does not state which time zone it uses. A meeting note in another city records a call at 6:20 in the evening. The two cities are in different time zones.', prompt:'What must be checked before comparing the times?', options:[['Assume both logs use the same time zone.',false],['Check which time zone each log uses before treating the times as the same moment.',true],['Treat the matching numbers as proof the logs describe one call.',false]], explanation:'Matching clock numbers in different time zones can describe different moments. The time zone of each record must be confirmed first.', observation:'A call log at 18:20 with no stated zone; a note at 6:20 in another zone.', inference:'Both records describe the same call.', alternative:'The calls may be hours apart, or they may be the same call recorded in different zones.' },
    { id:'crime-statement-later', track:'criminology', title:'Written three days later', format:'Source evaluation', difficulty:2, scenario:'A caretaker writes a detailed account of a Monday incident on Thursday. The account gives exact times to the minute, but the caretaker kept no notes on Monday and says the times are from memory.', prompt:'How should the exact times be treated?', options:[['Exact times from memory three days later are as reliable as a contemporaneous log.',false],['The account may be useful for sequence, but its minute-level times should be treated as approximate.',true],['A delayed account has no value at all.',false]], explanation:'Memory can preserve order and gist while losing precise timing. A delayed account can still help, with its precision downgraded.', observation:'A detailed account written three days later, times from memory, no Monday notes.', inference:'The minute-level times are exact.', alternative:'The sequence may be right while individual times drift, or a time may be reconstructed from routine rather than observed.' },
    { id:'crime-record-limits', track:'criminology', title:'A count shows a gap', format:'Evidence evaluation', difficulty:2, scenario:'A weekly inventory count at a community centre shows one projector missing. The count sheet records the total, the date, and the checker, but it does not record when the projector was last seen or who used it last.', prompt:'What does the count establish?', options:[['The count shows one projector is missing on that date.',false],['The count proves the last user took the projector.',false],['The count shows a missing item on that date; timing and responsibility are not established.',true]], explanation:'A count is a snapshot of what is present on one date. It does not show when an item left or who moved it.', observation:'A weekly count shows one projector missing; no last-seen time or last user is recorded.', inference:'The last user is responsible.', alternative:'The projector may have been moved for repair, loaned without a record, or miscounted in an earlier week.' },
    { id:'crime-two-sources-one-origin', track:'criminology', title:'Two reports, one origin', format:'Corroboration check', difficulty:2, scenario:'Two reports both say a gate was left open overnight. Both reports cite the same morning email from one supervisor, and neither author checked the gate themselves. No photo or log of the gate exists.', prompt:'What is the corroboration problem here?', options:[['The reports share a single origin, so they do not independently corroborate each other.',true],['Two reports always count as independent corroboration.',false],['The gate must have been closed because no photo exists.',false]], explanation:'Corroboration needs independent sources. Two reports that repeat one origin are one source counted twice.', observation:'Two reports cite the same supervisor email; neither author checked the gate.', inference:'The gate was left open overnight.', alternative:'The supervisor may have been mistaken, or the gate may have been opened and closed again before morning.' },
    { id:'crime-altered-or-offset', track:'criminology', title:'Offset or altered', format:'Evidence provenance', difficulty:3, scenario:'A system export shows file times one hour later than a paper log for the same events. The export was made after a daylight saving change, and the export settings were never documented. No edit history is available for the files.', prompt:'What is the most careful conclusion?', options:[['The difference is consistent with a clock or daylight saving offset, and tampering is not established.',true],['The one-hour difference proves the files were altered.',false],['The paper log must be wrong because the export is digital.',false]], explanation:'A systematic one-hour shift after a clock change points to a settings offset as a plausible cause. Without an edit history, alteration remains unproven.', observation:'Export times are one hour later than a paper log; daylight saving intervened; settings undocumented.', inference:'The files were deliberately altered.', alternative:'The export tool may have applied a different time zone, or the paper log times may have been approximate.' },
    { id:'crime-conflicting-accounts-detail', track:'criminology', title:'Two accounts, one bench', format:'Timeline analysis', difficulty:3, scenario:'In a park, Elena says a man in a blue jacket sat on a bench from 1:00 to 1:20. Tomas says a man in a grey jacket stood near the same bench at 1:10 and then walked away. Both accounts were given separately, and neither witness noted the other person present.', prompt:'What is the best interpretation?', options:[['Elena and Tomas must be describing two different men.',false],['The accounts conflict on jacket colour and posture, so identity and timing need an independent check.',true],['Tomas is right because standing is easier to notice than sitting.',false]], explanation:'Conflicting details on colour and posture leave identity uncertain. Separate accounts do not resolve each other without an independent record.', observation:'Elena reports blue jacket sitting 1:00 to 1:20; Tomas reports grey jacket standing at 1:10.', inference:'Two different men were present.', alternative:'One witness may have misremembered colour or posture, or the man may have changed position during the period.' },
    { id:'crime-preserve-first', track:'criminology', title:'The board was erased', format:'Chain of custody', difficulty:3, scenario:'A duty roster on a whiteboard was photographed only after it was partly erased and rewritten. The original roster is not saved elsewhere, and three staff members give different versions of the original shift times.', prompt:'What was lost, and what remains?', options:[['The original roster is lost as a record; the three recollections are separate claims to be compared, not a restored original.',true],['The rewritten board is a reliable copy of the original roster.',false],['The staff member who rewrote the board must have changed the times.',false]], explanation:'Once a fragile record is altered, the original cannot be recovered from the altered version. Recollections can be compared, but they do not recreate the record.', observation:'A whiteboard roster was partly erased and rewritten before a photo; no other copy exists.', inference:'The rewrite was deliberate falsification.', alternative:'The rewrite may have been a routine update, and the differing recollections may each be partly right.' },
    { id:'crime-incomplete-view-both', track:'criminology', title:'Two incomplete views', format:'Corroboration check', difficulty:3, scenario:'A camera shows a corridor from 7:00 to 7:05 but not the room at its end. A sign-in log shows a visitor at 7:03 but does not record which room they entered. The two records overlap in time but cover different facts.', prompt:'What can the two records together establish?', options:[['Together they prove the visitor entered the room at the end of the corridor.',false],['They show a corridor presence and a sign-in at overlapping times; the room entered is still not established.',true],['Because neither record is complete, both should be discarded.',false]], explanation:'Two partial records can each support what they cover without combining into a claim neither covers. Overlap in time is not overlap in subject.', observation:'Corridor footage 7:00 to 7:05; a sign-in at 7:03 with no room recorded.', inference:'The visitor entered the end room.', alternative:'The visitor may have entered another room, waited in the corridor, or left without entering any room.' },
    { id:'crime-handwriting-copy', track:'criminology', title:'A photocopy of a signature', format:'Evidence provenance', difficulty:3, scenario:'A file holds a photocopy of a signed permission slip. The original slip is lost, the photocopy is low quality, and the date on the copy is partly cut off. A second staff member recalls seeing the original but cannot recall its date.', prompt:'What can the photocopy support?', options:[['The photocopy shows a signature was copied, but its date and full wording cannot be reliably established from it.',true],['The photocopy proves the permission and its date.',false],['A low-quality copy proves the permission was forged.',false]], explanation:'A copy inherits the limits of its quality and completeness. A cut-off date and lost original leave the key details uncertain.', observation:'A low-quality photocopy with a cut-off date; the original is lost.', inference:'The permission was forged.', alternative:'The original may have been complete and genuine, with the copy losing detail in reproduction.' },
    { id:'crime-database-export', track:'criminology', title:'After the system move', format:'Evidence provenance', difficulty:3, scenario:'After a records system was moved to a new server, an export shows all event times shifted by one hour compared with printed reports from before the move. The migration notes do not mention time handling, and no one tested the export against a known event.', prompt:'What should happen before the export times are used?', options:[['Use the export times as printed, since the system is newer.',false],['Assume the printed reports were wrong and the export is right.',false],['Treat the export as possibly offset by migration, and test it against a known, independently timed event before relying on it.',true]], explanation:'A system change can shift recorded times without any deliberate change to the events. A known-event test can measure the offset before the export is trusted.', observation:'Export times shifted one hour after migration; no time-handling notes; no test against a known event.', inference:'The migration proves the old reports were wrong.', alternative:'The export may use a different time zone, or the printed reports may have used a local clock that also needs checking.' },
    { id:'crime-multiple-gaps', track:'criminology', title:'Three gaps, one morning', format:'Timeline analysis', difficulty:3, scenario:'A morning timeline has three separate gaps: 8:00 to 8:20, 9:05 to 9:40, and 10:15 to 10:30. A delivery, a phone call, and a room booking are each known only by a single time point that falls inside a different gap. No record links the three events to each other.', prompt:'What can be said about the order of the three events?', options:[['The delivery happened first, then the call, then the booking.',false],['The order cannot be established from single time points inside separate gaps with no linking record.',true],['The gaps prove the three events are unrelated.',false]], explanation:'A single time point inside a gap does not fix an event relative to events in other gaps. Order needs a record that connects them or tighter time bounds.', observation:'Three gaps and three events, each known by one time point in a different gap.', inference:'The events happened in the order listed.', alternative:'Any order is possible within the gaps, or an event time point may be approximate rather than exact.' },
    { id:'crime-source-chain', track:'criminology', title:'A story passed three times', format:'Source evaluation', difficulty:3, scenario:'A report about a lost laptop was told by a student to a teacher, then by the teacher to a supervisor, then by the supervisor to the person writing the file. Each retelling adds a detail about the time, and the written file does not say which details came from whom.', prompt:'What is the main reliability problem?', options:[['A story told three times is automatically false.',false],['The supervisor version should be treated as the original observation.',false],['Each retelling can add or change detail, and the file does not separate original observation from later additions.',true]], explanation:'Long chains of retelling can drift, especially on time and detail. A file that does not attribute details cannot show what was originally observed.', observation:'A laptop report passed through three people, with added time details and no attribution.', inference:'The final version is the accurate account.', alternative:'The original observation may have been simple, with time and detail added in retelling.' },
    { id:'crime-record-cannot-support', track:'criminology', title:'Present in the building', format:'Evidence evaluation', difficulty:3, scenario:'A building entry log shows a contractor named Sam entered at 1:00 and left at 4:00. A locked archive room on the third floor was found open at 3:30. The log does not record floor movements, and no camera covers the archive corridor.', prompt:'What does presence in the building establish?', options:[['Sam was in the building between 1:00 and 4:00.',false],['Sam opened the archive room at 3:30.',false],['Entry and exit times are supported; access to the archive room is not established by the log.',true]], explanation:'An entry log supports presence in the building, not presence in a particular room. Room access needs a record that covers that room.', observation:'Entry at 1:00, exit at 4:00, archive room found open at 3:30, no floor or corridor record.', inference:'Sam opened the archive room.', alternative:'The room may have been left open earlier, opened by another person, or found open for an ordinary reason.' },
    { id:'int-open-lunch', track:'interviewing', title:'Ask what happened, not what you expect', format:'Open question', difficulty:1, scenario:'Priya tells you she left the lunch room at 12:20 and noticed the supply closet door was open. You want her account in her own words.', prompt:'Which follow-up is most open?', options:[['"Did you see someone take supplies from the closet?"',false],['"What did you notice after you left the lunch room?"',true],['"Why did you not report the open door right away?"',false]], explanation:'The open question asks for what Priya noticed without suggesting a theft, a person, or a delay. Leading questions can add details she did not offer.', observation:'Priya left the lunch room at 12:20 and noticed an open supply closet door.', inference:'Someone took supplies, or Priya delayed reporting.', alternative:'The door may have been left open during routine restocking, and Priya may be reporting it promptly.' },
    { id:'int-reflect-notes', track:'interviewing', title:'Reflect back before you move on', format:'Reflect and clarify', difficulty:1, scenario:'Maya says the printer stopped at 3:10, she called support, and the call lasted about ten minutes. You want to check that you understood her.', prompt:'Which response best checks your understanding?', options:[['"So the printer stopped at 3:10 and you called support for about ten minutes. Did I get that right?"',true],['"So you were frustrated with support and gave up quickly."',false],['"That means the printer was broken all afternoon."',false]], explanation:'A brief summary in neutral words lets Maya correct any error. Adding frustration or a longer outage goes beyond what she said.', observation:'Maya reported a printer stop at 3:10 and a support call of about ten minutes.', inference:'Maya was frustrated, or the printer was broken all afternoon.', alternative:'Maya may have been calm, and the printer may have been fixed soon after the call.' },
    { id:'int-consent-purpose', track:'interviewing', title:'Explain why you are asking', format:'Consent and purpose', difficulty:1, scenario:'You need to ask a new teammate, Tom, about a scheduling mix-up on Tuesday. He has not been told why you are asking.', prompt:'What is the most respectful opening?', options:[['Start with detailed questions about Tuesday and see what he reveals.',false],['Ask him to guess why the schedule changed.',false],['"I am checking the Tuesday schedule so we can fix the rota. Is it okay to ask what you remember?"',true]], explanation:'Stating the purpose and asking permission respects Tom and helps him give a focused account. Surprise questions can confuse the issue.', observation:'Tom has not been told the purpose of the questions about Tuesday.', inference:'Tom knows the cause, or will reveal it under pressure.', alternative:'Tom may remember only part of the day, and a clear purpose may help him recall the relevant details.' },
    { id:'int-sequence-neutral', track:'interviewing', title:'Ask about order, not motive', format:'Neutral follow-up', difficulty:1, scenario:'Elena says she spoke to the receptionist, then she collected a parcel, then she returned to her desk at 11:00.', prompt:'Which question asks about sequence without suggesting a motive?', options:[['"You collected the parcel to avoid the receptionist, right?"',false],['"What happened between speaking to the receptionist and returning to your desk?"',true],['"Why did you take so long with the parcel?"',false]], explanation:'The neutral question asks about order and timing only. Questions about avoidance or delay suggest a motive Elena did not state.', observation:'Elena described three steps ending at her desk at 11:00.', inference:'Elena avoided someone, or delayed on purpose.', alternative:'The parcel collection may have taken a normal amount of time, and the steps may be routine.' },
    { id:'int-clarify-gently', track:'interviewing', title:'Clarify a detail without pressure', format:'Clarify without pressuring', difficulty:1, scenario:'Raj says a delivery arrived in the morning, but he is unsure whether it was before or after 10:00. You need the timing for a log.', prompt:'Which clarification is most gentle and neutral?', options:[['"Was it before or after 10:00, as best as you can remember?"',true],['"You must know the exact time if you were there."',false],['"It was before 10:00, was it not?"',false]], explanation:'The question invites the best recollection Raj can offer and accepts uncertainty. Demanding exactness or suggesting an answer can pressure him to guess.', observation:'Raj is unsure whether a morning delivery was before or after 10:00.', inference:'Raj is hiding the time, or the delivery time is exact in memory.', alternative:'Raj may remember the delivery in relation to another event, such as a meeting or a break.' },
    { id:'int-gaze-culture', track:'interviewing', title:'Gaze means different things', format:'Behavioural reasoning', difficulty:1, scenario:'A new colleague, Sofia, looks down while describing a busy shift. In her family, looking down while speaking to a senior colleague is a sign of respect.', prompt:'What is the fairest interpretation?', options:[['Sofia is avoiding the truth about the shift.',false],['Sofia is unsure and should be asked the same question again.',false],['Looking down is an observation; in this context it may signal respect, and it does not show deception.',true]], explanation:'Gaze norms vary by culture, relationship, and setting. One behavior cannot be read as proof of honesty or deception.', observation:'Sofia looked down while describing a busy shift.', inference:'Sofia is deceptive or uncertain.', alternative:'Sofia may be showing respect, thinking carefully, or following a cultural norm for the setting.' },
    { id:'int-pause-thinking', track:'interviewing', title:'A pause can mean thinking', format:'Behavioural reasoning', difficulty:1, scenario:'Ben pauses for several seconds before answering a question about a meeting on Thursday. He then gives a clear, detailed answer.', prompt:'What should you conclude from the pause alone?', options:[['Ben was inventing an answer.',false],['The pause alone shows little; Ben may have been recalling details before answering.',true],['Ben was hiding the real meeting time.',false]], explanation:'A pause often marks careful recall. Without other evidence, it does not show invention or concealment.', observation:'Ben paused, then gave a clear and detailed answer about Thursday.', inference:'Ben invented the answer or hid the time.', alternative:'Ben may have been checking his memory, choosing clear wording, or recalling a busy day.' },
    { id:'int-emotion-not-proof', track:'interviewing', title:'Emotion is not evidence', format:'Behavioural reasoning', difficulty:1, scenario:'Ana becomes tearful while describing a difficult customer interaction on Friday. She gives a consistent account of what the customer said.', prompt:'What is the most careful response?', options:[['"I can see this was difficult. Please take your time and tell me what happened in your own words."',true],['"Your tears show the customer must have threatened you."',false],['"Calm people tell the truth, so I need a calmer account."',false]], explanation:'Emotion can reflect stress, embarrassment, or relief, and it does not prove what the other person did. A calm, unhurried prompt protects the account.', observation:'Ana was tearful while giving a consistent account of a Friday interaction.', inference:'The customer threatened Ana, or emotion proves the account.', alternative:'Ana may be upset by the memory itself, and her account can still be checked against other records.' },
    { id:'int-leading-wording', track:'interviewing', title:'Wording can change recall', format:'Interviewing technique', difficulty:2, scenario:'Two students saw a bicycle fall near the library at 4:30. You ask one student, "How fast was the rider going when the bicycle smashed into the rack?" The other student is asked, "What happened near the library?"', prompt:'Which interview choice best protects both accounts?', options:[['Use the smashed wording with both students to keep questions identical.',false],['Ask the second student the same leading question so their answers match.',false],['Use neutral wording with both students, such as "What did you see happen?"',true]], explanation:'Leading words like smashed can suggest speed and damage that were not observed. Neutral wording lets each student report what they actually saw.', observation:'Two students saw the same event but were asked different questions.', inference:'The rider was speeding, or the bicycle was damaged.', alternative:'The bicycle may have tipped slowly, and the two accounts may differ only because the questions differed.' },
    { id:'int-recall-vs-news', track:'interviewing', title:'Separate what you saw from what you heard', format:'Memory and context', difficulty:2, scenario:'After a fire alarm on Monday, a staff member, Liam, says he saw smoke near the kitchen. He also read a group chat message that said smoke was seen near the kitchen.', prompt:'What is the best way to separate his own recall from the message?', options:[['"What did you personally see near the kitchen, apart from what the group chat said?"',true],['"The group chat was right, so your memory must match it."',false],['"Just repeat the group chat message so we have one version."',false]], explanation:'Asking Liam to separate personal observation from later information helps you judge the source of each detail. Agreement with a message is not the same as independent recall.', observation:'Liam saw the scene and also read a group chat message about it.', inference:'Liam personally saw smoke, or his memory is simply the message.', alternative:'Liam may have seen smoke before reading the message, and the two sources may agree by coincidence.' },
    { id:'int-stress-memory', track:'interviewing', title:'Memory under stress is uneven', format:'Memory and context', difficulty:2, scenario:'During a loud, crowded event on Saturday, a volunteer, Noor, was asked to watch the entrance. She remembers the music clearly but is unsure about the order of three visitors.', prompt:'What is the fairest way to treat her account?', options:[['Treat the whole account as unreliable because one part is uncertain.',false],['Accept the clear details as reported, note the uncertain order, and check the order against a log if one exists.',true],['Assume the clearest memory must be the most accurate part.',false]], explanation:'Stress and noise can affect some details more than others. A careful interview records what is clear, marks what is uncertain, and seeks corroboration.', observation:'Noor remembers the music clearly but is unsure about the order of three visitors.', inference:'All of her memory is unreliable, or the clearest part is the most accurate.', alternative:'Noor may recall faces or times well, and a sign-in log may resolve the order.' },
    { id:'int-fidget-context', track:'interviewing', title:'Check the context of a movement', format:'Behavioural reasoning', difficulty:2, scenario:'During a cold morning interview in an unheated room, a customer, Omar, taps his foot and rubs his hands while answering questions about a refund.', prompt:'What is the most reasonable reading of the movement?', options:[['Omar is nervous because he is making a false claim.',false],['Omar is impatient and should be asked to stop moving.',false],['The tapping and rubbing may reflect cold, habit, or discomfort, and they do not show deception.',true]], explanation:'Movement has many causes, including temperature, habit, and stress. It cannot be used as a test of honesty without other evidence.', observation:'Omar tapped his foot and rubbed his hands in a cold room.', inference:'Omar is nervous about a false refund claim.', alternative:'Omar may be cold, restless by habit, or uncomfortable in an unfamiliar setting.' },
    { id:'int-expression-culture', track:'interviewing', title:'Expressions vary by person and place', format:'Behavioural reasoning', difficulty:2, scenario:'A teammate, Yuki, smiles while describing a serious delay on Wednesday. In her usual style, she smiles when she is embarrassed or trying to stay polite in a difficult conversation.', prompt:'What is the fairest interpretation?', options:[['The smile is an observation; it may reflect embarrassment or politeness, and it does not show that she finds the delay funny.',true],['The smile proves she does not take the delay seriously.',false],['The smile shows she is hiding the cause of the delay.',false]], explanation:'Facial expression is shaped by culture, habit, and social context. Without knowing a personal baseline, a smile cannot be read as amusement or concealment.', observation:'Yuki smiled while describing a serious delay on Wednesday.', inference:'Yuki finds the delay funny, or is hiding its cause.', alternative:'Yuki may smile when embarrassed, and her words about the delay can be checked against the schedule.' },
    { id:'int-reflect-check', track:'interviewing', title:'Reflect, then ask one clear question', format:'Reflect and clarify', difficulty:2, scenario:'A neighbour, Carla, says the hallway light flickered at 9:00, she heard footsteps, and she locked her door. You want to confirm the order without adding details.', prompt:'Which response does this best?', options:[['"So you heard footsteps because someone was trying to enter."',false],['"So the light flickered at 9:00, you heard footsteps, and then you locked your door. Is that the right order?"',true],['"You must have been frightened, so tell me about the intruder."',false]], explanation:'Reflecting the stated order back in neutral words lets Carla correct it if needed. Adding a motive or an intruder goes beyond her account.', observation:'Carla reported a flickering light, footsteps, and locking her door.', inference:'Someone tried to enter, or Carla was frightened by an intruder.', alternative:'The footsteps may have been a neighbour, and the flicker may have been a faulty bulb.' },
    { id:'int-pressure-repeat', track:'interviewing', title:'Repeating a question can pressure an answer', format:'Clarify without pressuring', difficulty:2, scenario:'A student, Alex, says he does not remember whether the class started at 9:00 or 9:15. An interviewer asks the same question three times, louder each time, until Alex picks 9:00.', prompt:'What is the problem with this approach?', options:[['Alex should have remembered the exact time.',false],['Repeating the question proves Alex was lying the first time.',false],['Repeated pressure can lead a person to guess to end the questioning, so the answer may not reflect real recall.',true]], explanation:'Pressure can produce compliance rather than memory. A single neutral question, plus a check against a timetable, protects the account.', observation:'Alex first said he did not remember, then picked 9:00 after repeated loud questioning.', inference:'Alex was lying, or should have known the exact time.', alternative:'Alex may have guessed under pressure, and the timetable may show the correct start time.' },
    { id:'int-sequence-time', track:'interviewing', title:'Ask about time without filling gaps', format:'Neutral follow-up', difficulty:2, scenario:'A colleague, Dana, says she sent an email, attended a call, and then spoke to a manager, but she does not remember the times. You need the order for a record.', prompt:'Which question best preserves the gaps in her memory?', options:[['"Can you tell me the order of those three things, and say which parts you are unsure about?"',true],['"You sent the email at 10:00, then took the call, right?"',false],['"Why can you not remember such a simple morning?"',false]], explanation:'Asking for order while inviting Dana to mark uncertainty keeps gaps visible. Suggesting a time or criticising her memory can create false precision.', observation:'Dana remembers three events but not their times.', inference:'Dana knows the times, or the email was sent at 10:00.', alternative:'Dana may recall the order through the call notes or the email timestamp.' },
    { id:'int-consent-boundary', track:'interviewing', title:'Respect a boundary and offer a choice', format:'Consent and purpose', difficulty:2, scenario:'A customer, Farah, is asked about a personal health issue that affected her visit on Thursday. She looks uncomfortable and says she would rather not discuss it.', prompt:'What is the most respectful next step?', options:[['Keep asking, because the detail might be useful later.',false],['"That is fine, we can skip that. Is there anything about the visit itself you would like to add?"',true],['"If you do not answer, I will have to assume the worst."',false]], explanation:'Consent includes the right to decline a personal question. Offering to skip it and return to the visit keeps the conversation respectful and useful.', observation:'Farah declined to discuss a personal health issue about Thursday.', inference:'Farah is hiding something important, or must answer to be believed.', alternative:'Farah may share relevant visit details without discussing her health, or may choose to add them later.' },
    { id:'int-contamination-group', track:'interviewing', title:'Group talk can shape recall', format:'Memory and context', difficulty:3, scenario:'Three teammates discussed a missed delivery in a group chat for an hour before you spoke to one of them, Hana. Hana now repeats several phrases from the chat.', prompt:'What is the most careful approach?', options:[['Treat the repeated phrases as proof Hana copied the chat.',false],['"Please tell me what you personally noticed about the delivery, in your own words, and note anything you learned from the chat."',true],['"Just agree with the group chat version so we can move on."',false]], explanation:'Group discussion can add wording and details to later recall. Asking Hana to separate personal observation from chat content helps you weigh each part.', observation:'Hana discussed the delivery in a group chat before the interview and repeats chat phrases.', inference:'Hana copied the chat, or the chat version is her own memory.', alternative:'Hana may have noticed the same details independently, and the chat may have only given her words for them.' },
    { id:'int-motive-sequence', track:'interviewing', title:'Sequence first, motive later', format:'Neutral follow-up', difficulty:3, scenario:'A volunteer, Leo, says he checked the gate, spoke to a visitor, and then left the site at 6:00. A second account says the gate was open at 6:15. You need to understand the sequence before considering any explanation.', prompt:'Which question keeps sequence separate from motive?', options:[['"You left the gate open because you were in a hurry, did you not?"',false],['"Why did you leave the site before checking the gate again?"',false],['"Can you walk me through what you did at the gate, step by step, and what you saw at each step?"',true]], explanation:'A step-by-step account establishes what happened before any motive is considered. Questions that assume haste or carelessness can distort the sequence.', observation:'Leo described three steps ending at 6:00; a second account reports an open gate at 6:15.', inference:'Leo was in a hurry, or left the gate open on purpose.', alternative:'The gate may have been opened after Leo left, or the second account may refer to a different gate.' },
    { id:'int-stress-delay', track:'interviewing', title:'Stress, delay, and a changed detail', format:'Memory and context', difficulty:3, scenario:'Two weeks after a noisy, stressful incident at a market, a witness, Sara, changes one detail: she first said a stall was blue, now she says it was green. Her account of the sequence has stayed the same.', prompt:'What is the most balanced assessment?', options:[['"One changed colour after two weeks does not prove the whole account is false; memory for a detail can fade while sequence recall stays stable."',true],['"The changed colour proves Sara invented the whole incident."',false],['"Sara must be lying, because honest witnesses never change a detail."',false]], explanation:'Memory can fade or shift for a peripheral detail over time, especially after stress, while central sequence recall remains stable. The change is a reason to check, not to dismiss the account.', observation:'Sara changed one colour detail after two weeks; her sequence account stayed the same.', inference:'Sara invented the incident, or honest witnesses never change details.', alternative:'Sara may have misremembered the colour at first, or learned the correct colour later and updated her account.' },
    { id:'int-gaze-neurotype', track:'interviewing', title:'No single baseline for gaze', format:'Behavioural reasoning', difficulty:3, scenario:'A student, Kai, looks away while recalling a timetable, looks at you while listening, and fidgets with a pen throughout. Kai has told you before that eye contact feels uncomfortable and that fidgeting helps him focus.', prompt:'What is the fairest reading?', options:[['Kai is avoiding the truth whenever he looks away.',false],['Gaze and fidgeting vary by person, neurotype, and task; without a personal baseline, they do not show deception, and the timetable can be checked directly.',true],['Kai must be forced to make eye contact so his answers can be judged.',false]], explanation:'For some people, looking away aids recall and fidgeting aids focus. Judging honesty from gaze would ignore that variation and miss the direct check.', observation:'Kai looks away while recalling, looks at you while listening, and fidgets with a pen.', inference:'Kai is deceptive, or eye contact is required for truthful answers.', alternative:'Kai may recall better while looking away, and the timetable record may confirm or correct his account.' },
    { id:'int-leading-detail', track:'interviewing', title:'A suggested detail can enter recall', format:'Interviewing technique', difficulty:3, scenario:'An interviewer asks a witness, "Did you see the red van parked by the side door?" The witness later says she saw a red van, although earlier she mentioned only a vehicle. No other record mentions a van colour.', prompt:'What is the most careful next step?', options:[['Record the red van as confirmed, because the witness agreed.',false],['Ask the witness to repeat the red van detail until she is certain.',false],['"Before I mentioned a colour, what did you notice about the vehicle?" Then check for an independent record of the vehicle.',true]], explanation:'A suggested colour can enter later recall, so agreement after a leading question is weak evidence. Returning to the pre-suggestion account and seeking corroboration protects the record.', observation:'The witness mentioned only a vehicle before the interviewer suggested a red van.', inference:'The witness saw a red van, or agreement confirms the detail.', alternative:'The witness may have seen a different vehicle, or no vehicle at all, and the colour may have come from the question.' },
    { id:'int-clarify-conflict', track:'interviewing', title:'Clarify a conflict without taking sides', format:'Clarify without pressuring', difficulty:3, scenario:'Two customers give different accounts of a refund on Friday. One says the refund was given at 2:00, the other says 4:30. Both seem confident, and both were in the shop that afternoon.', prompt:'Which approach best resolves the time difference?', options:[['"Can each of you tell me, step by step, what you did that afternoon, and what you are unsure about?" Then compare both accounts with the till record.',true],['"One of you must be lying, so tell me which time is true."',false],['"The more confident person is probably right, so I will use their time."',false]], explanation:'Confidence does not settle a factual conflict. Neutral step-by-step accounts, plus an independent till record, can separate a real difference from a memory error.', observation:'Two confident accounts differ on a refund time, 2:00 versus 4:30.', inference:'One customer is lying, or confidence proves accuracy.', alternative:'One account may confuse the refund with another transaction, or the till record may show a different time.' },
    { id:'int-purpose-sensitive', track:'interviewing', title:'Sensitive topics need purpose and pause', format:'Consent and purpose', difficulty:3, scenario:'You need to ask a colleague, Amara, about a private family matter that may explain an absence on Monday. She has not agreed to discuss family matters at work, and the absence can be checked in the rota.', prompt:'What is the most respectful approach?', options:[['Ask about the family matter first, because it might explain the absence.',false],['Check the rota first, explain why you are asking, ask if she is willing to discuss it, and accept a refusal without penalty.',true],['"If you will not discuss your family, I cannot accept the absence."',false]], explanation:'A sensitive question needs a clear purpose, explicit consent, and a real choice to decline. Checking the rota first may answer the work question without personal detail.', observation:'Amara has not agreed to discuss family matters, and the absence is in the rota.', inference:'Amara must discuss her family to explain the absence.', alternative:'Amara may choose to share a brief explanation later, or the rota may resolve the question on its own.' },
    { id:'int-expression-stress', track:'interviewing', title:'Expression without a baseline', format:'Behavioural reasoning', difficulty:3, scenario:'A witness, Jon, shows little facial expression while describing a serious accident he saw on Sunday. You have never met Jon before, and you do not know how he usually expresses emotion.', prompt:'What can you responsibly conclude from his expression?', options:[['Jon is unfeeling, so his account is less credible.',false],['Jon is calm, so his account must be accurate.',false],['Very little; without a personal baseline, flat expression may reflect shock, culture, habit, or personality, and the account should be checked against other evidence.',true]], explanation:'Expression varies widely, and shock can flatten it. Without knowing how Jon usually expresses emotion, his face cannot judge his credibility.', observation:'Jon showed little expression while describing a serious accident on Sunday.', inference:'Jon is unfeeling, or calm expression proves accuracy.', alternative:'Jon may be in shock, may express emotion quietly, or may be focused on giving an accurate account.' },
    { id:'int-recall-source', track:'interviewing', title:'Did you see it, hear it, or hear about it?', format:'Memory and context', difficulty:3, scenario:'A neighbour, Ruth, says a package was left at the front door at noon. When asked how she knows, she says she heard a knock, saw a courier uniform through a window, and later read a delivery notice.', prompt:'Which question best sorts the sources of her knowledge?', options:[['"What did you see yourself, what did you hear, and what did you learn from the notice?"',true],['"So you saw the package delivered at noon, correct?"',false],['"The notice is enough, so your own observations do not matter."',false]], explanation:'Separating seeing, hearing, and reading helps you judge each source. A delivery notice can confirm a time without replacing direct observation.', observation:'Ruth heard a knock, saw a uniform through a window, and later read a delivery notice.', inference:'Ruth saw the package delivered, or the notice alone settles the account.', alternative:'Ruth may have seen a different courier, or the notice may refer to a different delivery.' },
    { id:'strat-objective-first', track:'strategy', title:'Start with the objective', format:'Decision framing', difficulty:1, scenario:'Maya must choose a venue for a Saturday team lunch for twelve people. Two places fit the budget, one is noisy and one needs a deposit by Friday, and she has not yet said what matters most.', prompt:'What is the best first step?', options:[['State what a good lunch looks like, including budget, noise, and access, before comparing venues.',true],['Pick the venue with the nicest photos and announce it today.',false],['Ask every guest to rank all twelve restaurants in town.',false]], explanation:'A clear objective turns a vague choice into a testable comparison.', observation:'Two venues fit the budget; one is noisy and one needs a Friday deposit.', inference:'The prettier venue must be the better choice.', alternative:'The quieter venue may suit conversation better, or the deposit may be refundable.' },
    { id:'strat-reversible-test', track:'strategy', title:'Try the reversible step first', format:'Reversibility check', difficulty:1, scenario:'At a small shop, Ravi is unsure whether a new shelf layout will help customers. Moving one shelf takes twenty minutes and can be undone, while repainting the whole wall takes a day and cannot be undone easily.', prompt:'Which move is best while the result is unknown?', options:[['Repaint the wall first to show confidence in the new layout.',false],['Move one shelf, watch customer flow for an afternoon, then decide about the wall.',true],['Leave the layout unchanged and guess which change would have worked.',false]], explanation:'A small reversible test produces real evidence before a costly irreversible change.', observation:'One shelf move is quick and reversible; repainting is slow and hard to undo.', inference:'A bold permanent change proves the new layout works.', alternative:'Customer flow may improve, stay the same, or worsen, and the test will show which.' },
    { id:'strat-small-check-first', track:'strategy', title:'Check one decision-relevant fact', format:'Strategic decision', difficulty:1, scenario:'Priya is planning a Sunday market stall and hears that rain is possible. She can check the hourly forecast in two minutes, or spend an hour packing for every weather outcome.', prompt:'What is the best next step?', options:[['Pack for every outcome before checking anything.',false],['Cancel the stall because rain is possible.',false],['Check the hourly forecast first, then pack for the most likely conditions.',true]], explanation:'A quick relevant check narrows the options before spending effort.', observation:'Rain is possible; a forecast check takes two minutes.', inference:'Possible rain means the stall will fail.', alternative:'The rain may arrive late, miss the market, or be light enough to manage.' },
    { id:'strat-name-success', track:'strategy', title:'Name what success looks like', format:'Decision framing', difficulty:1, scenario:'Jon is organising a Friday evening quiz for twenty neighbours. He has a hall, a set of questions, and a small prize budget, but no agreed finish time or plan for ties.', prompt:'What should Jon settle first?', options:[['Buy more prizes in case the quiz runs long.',false],['Agree on a finish time, a tie rule, and what a good evening looks like, then finalise the questions.',true],['Let the quiz run until everyone leaves.',false]], explanation:'Naming success and limits first keeps later choices proportionate and fair.', observation:'A hall, questions, and a prize budget are ready; finish time and tie rule are undecided.', inference:'More prizes will make the evening succeed.', alternative:'A short, well-paced quiz may work better than a long one with extra prizes.' },
    { id:'strat-time-box-check', track:'strategy', title:'Use the time you have', format:'Strategic decision', difficulty:1, scenario:'Aisha has fifteen minutes before a team meeting to decide whether to move a delivery from Tuesday to Wednesday. The supplier can confirm the change by phone in three minutes.', prompt:'What is the best use of the fifteen minutes?', options:[['Call the supplier, confirm the change and its cost, then decide.',true],['Wait until after the meeting and hope the Tuesday slot still works.',false],['Email five people for opinions before checking the supplier.',false]], explanation:'A short direct check fits the time available and answers the decision.', observation:'Fifteen minutes remain; a three-minute call can confirm the change.', inference:'Asking more people will settle a supplier question.', alternative:'The supplier may offer a free change, a fee, or a better slot.' },
    { id:'strat-ask-permission-first', track:'strategy', title:'Ask before checking private records', format:'Decision framing', difficulty:1, scenario:'Ben wants to check a colleague shift record to settle a rota question. The record is private, the colleague is at lunch, and the rota can wait until the afternoon.', prompt:'What is the fairest next step?', options:[['Open the record now because the question is urgent to Ben.',false],['Guess the shift pattern from last week.',false],['Wait, ask the colleague for permission, and check only the detail the rota needs.',true]], explanation:'A proportionate check respects privacy and still answers the question.', observation:'The record is private; the colleague is away; the rota can wait.', inference:'Urgency justifies opening a private record without permission.', alternative:'The colleague may confirm the shift quickly, or suggest a different source.' },
    { id:'strat-one-question-test', track:'strategy', title:'One question that could change the plan', format:'Information-value strategy', difficulty:1, scenario:'Sara is choosing between two caterers for a family dinner. Both cost the same, but one needs a final guest count by Thursday and the other can adjust on the day.', prompt:'Which question is most useful?', options:[['Choose the caterer with the longer menu without checking flexibility.',false],['Ask which caterer can adjust if two extra guests arrive, then choose on that answer.',true],['Book both caterers to avoid deciding.',false]], explanation:'One decision-relevant question can separate options that look equal on price.', observation:'Prices are equal; deadlines and flexibility differ.', inference:'A longer menu must mean better value.', alternative:'Guest numbers may stay fixed, making flexibility less important.' },
    { id:'strat-pause-before-announce', track:'strategy', title:'Pause before a public decision', format:'Reversibility check', difficulty:1, scenario:'Tom hears a rumour that a local club may close on Mondays. He runs the club notice board and is tempted to post the rumour today, before checking with the manager.', prompt:'What should Tom do first?', options:[['Check with the manager first, then post only what is confirmed.',true],['Post the rumour now so members hear it first.',false],['Post a guess about the new hours to start discussion.',false]], explanation:'A brief private check prevents spreading an unconfirmed claim.', observation:'The closure is a rumour; the manager can confirm it.', inference:'Posting early shows good leadership.', alternative:'The manager may confirm a change, deny it, or share a different plan.' },
    { id:'strat-compare-three-options', track:'strategy', title:'Compare three options fairly', format:'Trade-off choice', difficulty:2, scenario:'Elena must replace a broken office printer. Option one is cheap to buy but costly to run, option two is dearer but cheaper per page, and option three is a shared printer on another floor.', prompt:'How should Elena compare the options?', options:[['Pick the cheapest purchase price and ignore running costs.',false],['Pick the dearest machine because price signals quality.',false],['Compare purchase price, running cost, and walking time for each option, then choose the lowest total burden.',true]], explanation:'Comparing the same costs for every option reveals the real trade-off.', observation:'Three printers differ in purchase price, running cost, and location.', inference:'The lowest sticker price is the cheapest choice.', alternative:'The shared printer may be cheapest overall, or its inconvenience may outweigh the saving.' },
    { id:'strat-sequence-before-judgment', track:'strategy', title:'Gather before judging', format:'Sequencing', difficulty:2, scenario:'A school team must decide why attendance fell at a Tuesday workshop. They have sign-in sheets, a short feedback form, and a note about a bus delay, but no one has read them together yet.', prompt:'What order best protects the reasoning?', options:[['Read the sign-in sheets and feedback first, then list two or three explanations that fit the records.',true],['Decide the cause from the bus note alone.',false],['Ask the loudest participant for the reason and accept it.',false]], explanation:'Reviewing records before judging keeps the first explanation from shaping the evidence.', observation:'Sign-in sheets, feedback, and a bus note are available but unread together.', inference:'One note explains the whole drop in attendance.', alternative:'Timing, topic, weather, or transport may each explain part of the change.' },
    { id:'strat-check-in-point', track:'strategy', title:'Set a check-in point', format:'Update the plan', difficulty:2, scenario:'Noah is testing a new morning routine for a delivery team for two weeks. He wants to know if start times improve, without changing the whole rota on day one.', prompt:'What is the best way to run the test?', options:[['Change the whole rota now and review it in three months.',false],['Agree what to measure, run the routine for two weeks, and review the results on a set date.',true],['Keep changing the routine daily based on each morning.',false]], explanation:'A set check-in gives the test time to work and a clear moment to judge it.', observation:'A two-week test is planned; the rota is not yet changed.', inference:'Daily changes will reveal the best routine faster.', alternative:'The routine may help, hurt, or make no difference, and the review will show which.' },
    { id:'strat-what-would-change-mind', track:'strategy', title:'Say what would change your view', format:'Information-value strategy', difficulty:2, scenario:'Lena thinks a charity raffle will raise more money on Saturday than on Friday. She has last year ticket sales, a hall booking, and a volunteer list, but the two days have never been compared directly.', prompt:'What is the strongest next move?', options:[['State in advance what result would favour Saturday, then compare last year sales for both days.',true],['Choose Saturday because it feels busier.',false],['Run the raffle on both days to avoid choosing.',false]], explanation:'Naming the deciding evidence in advance prevents the result from being read to fit a preference.', observation:'Last year sales exist; Saturday and Friday were never compared directly.', inference:'A busy feeling proves Saturday will raise more.', alternative:'Friday may suit regular donors better, or the difference may be small.' },
    { id:'strat-proportionate-effort', track:'strategy', title:'Match effort to the stakes', format:'Trade-off choice', difficulty:2, scenario:'Omar must decide whether to move a small team meeting from 10 am to 11 am. The room is free at both times, two people prefer 11 am, and no client is affected.', prompt:'What is the proportionate response?', options:[['Spend a day surveying everyone and writing a report.',false],['Refuse any change because the original time was agreed.',false],['Make the low-cost change, note it clearly, and move on to higher-stakes work.',true]], explanation:'A small reversible decision deserves a small amount of effort.', observation:'The room is free at both times; no client is affected.', inference:'Every schedule change needs a full review.', alternative:'The 11 am slot may suit the team better, or create a new clash later.' },
    { id:'strat-private-first', track:'strategy', title:'Start private, stay fair', format:'Decision framing', difficulty:2, scenario:'A manager hears that two staff members disagree about a shared task. No customer is affected yet, and both staff members are willing to talk separately first.', prompt:'What is the fairest sequence?', options:[['Announce the disagreement to the whole team to force a quick resolution.',false],['Speak to each person privately, agree what the task needs, then bring them together with a clear plan.',true],['Reassign the task without asking either person what happened.',false]], explanation:'A private first step protects fairness and gathers facts before a joint discussion.', observation:'Two staff members disagree; no customer is affected; both will talk separately.', inference:'A public announcement will resolve a private disagreement.', alternative:'The disagreement may be about unclear roles, timing, or workload, not intent.' },
    { id:'strat-reversible-pilot', track:'strategy', title:'Pilot before committing', format:'Reversibility check', difficulty:2, scenario:'A cafe owner wants to add a Saturday breakfast menu. A full launch needs new stock, extra staff, and printed menus, while a one-Saturday trial needs only a small order and a chalkboard sign.', prompt:'What is the best next step?', options:[['Run a one-Saturday trial with a small menu, measure sales and waste, then decide on a full launch.',true],['Launch the full menu at once to avoid a slow start.',false],['Add breakfast every day without testing demand.',false]], explanation:'A pilot tests demand with limited cost and leaves room to adjust.', observation:'A trial is small and reversible; a full launch is costly.', inference:'A full launch proves demand exists.', alternative:'Saturday demand may be strong, weak, or limited to a few dishes.' },
    { id:'strat-update-after-new-record', track:'strategy', title:'Update when the record changes', format:'Update the plan', difficulty:2, scenario:'Karen planned a garden event for Sunday based on a forecast of dry weather. On Saturday evening a new forecast shows heavy rain from noon, and a covered hall is free until 9 am Sunday.', prompt:'What should Karen do with the new forecast?', options:[['Keep the garden plan because it was already announced.',false],['Cancel the event without checking the hall.',false],['Use the new forecast to move the event to the hall, explain the change, and keep the same start time.',true]], explanation:'A plan should change when new evidence changes the conditions it relied on.', observation:'A new forecast shows heavy rain; a covered hall is free until 9 am.', inference:'Sticking to an announced plan is always best.', alternative:'The rain may arrive late, but the hall removes the main risk.' },
    { id:'strat-cost-of-waiting', track:'strategy', title:'Weigh waiting against acting', format:'Trade-off choice', difficulty:2, scenario:'David can book a community hall now for 80 dollars, or wait a week in case a cheaper hall opens. The cheaper hall is uncertain, and the first hall may be taken by another group.', prompt:'How should David decide?', options:[['Wait for the cheaper hall without checking its availability.',false],['Compare the certain 80-dollar booking with the uncertain saving and the risk of losing the date, then decide.',true],['Book both halls to keep every option open.',false]], explanation:'Waiting has a cost too, so compare certainty, saving, and risk together.', observation:'One hall costs 80 dollars now; a cheaper hall is uncertain.', inference:'Waiting always saves money.', alternative:'The cheaper hall may open, stay closed, or cost more after travel.' },
    { id:'strat-competing-constraints', track:'strategy', title:'Balance competing constraints', format:'Decision framing', difficulty:3, scenario:'A clinic team must reschedule six appointments after a power cut. Patients need timely care, staff need a fair workload, and only two rooms are available on Tuesday afternoon.', prompt:'What is the best approach?', options:[['Fit all six appointments into Tuesday regardless of staff load.',false],['Rank appointments by urgency, spread the load fairly, and offer clear alternatives for those who must wait.',true],['Cancel all six and rebook them in order of arrival.',false]], explanation:'When constraints compete, rank by need, protect fairness, and explain the trade-off.', observation:'Six appointments, two rooms, and a fair workload limit compete.', inference:'Fitting everyone in at once is the fairest outcome.', alternative:'Some patients may prefer a later date, freeing a slot for an urgent case.' },
    { id:'strat-information-value-tradeoff', track:'strategy', title:'Choose the check that discriminates', format:'Information-value strategy', difficulty:3, scenario:'Three explanations fit a missing delivery: wrong address, delayed courier, or a lost parcel. A tracking update can rule out two of them in five minutes, while calling every neighbour takes an hour.', prompt:'Which check should come first?', options:[['Check the tracking update first because it can separate the explanations quickly.',true],['Call every neighbour before checking tracking.',false],['Assume the parcel is lost and order a replacement at once.',false]], explanation:'The best check is the one that most clearly separates the live explanations.', observation:'Three explanations fit; tracking can rule out two in five minutes.', inference:'More effort always produces better evidence.', alternative:'Tracking may be out of date, so a neighbour check may still be needed later.' },
    { id:'strat-bias-resistant-sequence', track:'strategy', title:'Protect the sequence from bias', format:'Sequencing', difficulty:3, scenario:'A hiring panel must review twenty applications for one role. One panel member already favours a candidate they know, and the panel has agreed scoring criteria but has not used them yet.', prompt:'What sequence best protects the decision?', options:[['Let the panel member present their favourite candidate first.',false],['Score applications after discussing the known candidate.',false],['Score every application against the agreed criteria first, then discuss the scores together.',true]], explanation:'Scoring before discussion prevents an early favourite from shaping later judgments.', observation:'Twenty applications and agreed criteria exist; one member favours a known candidate.', inference:'A known candidate must be the strongest applicant.', alternative:'The known candidate may score well, or another applicant may score higher.' },
    { id:'strat-revise-plan-publicly', track:'strategy', title:'Revise a plan without losing trust', format:'Update the plan', difficulty:3, scenario:'A youth club leader announced a Friday trip, then learns the bus costs twice the budget. A shorter local trip fits the budget, and parents need an answer by Wednesday.', prompt:'What is the best revision?', options:[['Keep the original trip and ask parents for extra money at the last minute.',false],['Explain the bus cost, offer the shorter local trip, and ask parents to confirm by Wednesday.',true],['Cancel the trip silently and say nothing to parents.',false]], explanation:'A clear revision with reasons and a deadline preserves trust and keeps a workable plan.', observation:'Bus costs doubled; a local trip fits the budget; parents need an answer by Wednesday.', inference:'Changing a plan always damages trust.', alternative:'Parents may prefer a later original trip, or accept the local option.' },
    { id:'strat-uncertain-stakeholder', track:'strategy', title:'Decide with an absent stakeholder', format:'Decision framing', difficulty:3, scenario:'A volunteer group must choose a new meeting night. Four members prefer Thursday, three prefer Tuesday, and the treasurer, who holds the keys, is away and cannot be reached until Monday.', prompt:'What is the best next step?', options:[['Shortlist Thursday and Tuesday, check key access on Monday, and confirm only after the treasurer replies.',true],['Choose Thursday now and assume the keys will be available.',false],['Pick a third night that no one prefers to avoid a vote.',false]], explanation:'A decision that depends on an absent person should wait for the fact it depends on.', observation:'Four prefer Thursday, three prefer Tuesday; the key holder is away until Monday.', inference:'A majority vote settles access as well as preference.', alternative:'The treasurer may support either night, or offer a different key arrangement.' },
    { id:'strat-two-stage-decision', track:'strategy', title:'Split a big decision in two', format:'Sequencing', difficulty:3, scenario:'A small business must choose new accounting software. The choice is costly to reverse, the team has two weeks, and a free trial can test the main features in three days.', prompt:'How should the business decide?', options:[['Buy the most expensive software now to end the debate.',false],['Keep the old software and ignore the trial.',false],['Use the three-day trial to test the main features, then buy only if the trial meets the agreed needs.',true]], explanation:'A trial stage separates testing from committing, so the final choice rests on evidence.', observation:'The purchase is costly to reverse; a three-day trial can test main features.', inference:'Price alone shows which software fits the team.', alternative:'The trial may reveal a simpler tool, or confirm the first choice.' },
    { id:'strat-evidence-threshold', track:'strategy', title:'Set the threshold before acting', format:'Information-value strategy', difficulty:3, scenario:'A neighbourhood group is considering a formal complaint about late-night noise. They have three dated notes, one recording, and a neighbour who denies the noise, but no agreed standard for what counts as enough evidence.', prompt:'What should the group do first?', options:[['File the complaint now because three notes feel like enough.',false],['Agree what evidence would justify a complaint, gather it fairly, and act only if that threshold is met.',true],['Collect notes for a year before deciding anything.',false]], explanation:'An agreed threshold prevents a complaint based on feeling alone or delayed by endless collection.', observation:'Three notes and one recording exist; no standard for enough evidence is agreed.', inference:'Any notes at all prove a formal complaint is justified.', alternative:'More records may support the complaint, or show the noise is occasional.' },
    { id:'strat-fair-process-under-pressure', track:'strategy', title:'Keep process fair under pressure', format:'Decision framing', difficulty:3, scenario:'A sports club must select twelve players from eighteen for a Saturday match. The coach is under time pressure, two selectors disagree, and parents are waiting for the list by 6 pm.', prompt:'What is the fairest way to meet the deadline?', options:[['Use the agreed selection criteria, record the reasons briefly, and publish the list by 6 pm with a clear review route.',true],['Pick the twelve fastest players without recording reasons.',false],['Delay the list until after the match to avoid disagreement.',false]], explanation:'Agreed criteria and a brief record keep a pressured decision fair and checkable.', observation:'Eighteen players compete for twelve places; selectors disagree; a 6 pm deadline applies.', inference:'Speed matters more than a recorded reason.', alternative:'A player left out may have a strong case on criteria the coach overlooked.' },
    { id:'strat-long-horizon-review', track:'strategy', title:'Review a plan over a longer horizon', format:'Trade-off choice', difficulty:3, scenario:'A family is choosing a heating plan for winter. A cheap monthly plan costs more over five years, a dearer plan saves money over five years, and the family may move in three years.', prompt:'How should the family compare the plans?', options:[['Choose the cheapest monthly cost and ignore the five-year total.',false],['Choose the five-year saving without checking the moving plan.',false],['Compare total cost over three years and five years, check the moving terms, then choose for the most likely stay.',true]], explanation:'A longer horizon and a check on the moving plan prevent a short-term saving from becoming a long-term loss.', observation:'One plan is cheap monthly but costly over five years; the family may move in three years.', inference:'The lowest monthly payment is always the best deal.', alternative:'Staying five years may favour the dearer plan, while moving early may favour the cheap one.' },
  ],
  baseline: [
    { prompt:'A person answers slowly, then changes a small detail in their story. What can you responsibly conclude?', options:[['That they are lying.',false],['You have an inconsistency to clarify; its cause is not established.',true],['That the changed detail is the most important one.',false]], why:'A discrepancy is worth checking, but memory, wording, stress, or an innocent correction can explain it.' },
    { prompt:'You find one record that supports your leading explanation. What should you do next?', options:[['Look for an independent source and evidence that could challenge it.',true],['Stop; one supporting record settles the question.',false],['Ask a question that suggests the answer you expect.',false]], why:'Independent corroboration and disconfirming tests help avoid confirmation bias.' },
    { prompt:'Which sentence is an observation rather than an inference?', options:[['“She crossed her arms because she was defensive.”',false],['“She folded her arms while standing by the doorway.”',true],['“She did not trust the group.”',false]], why:'The second sentence describes what could be seen. The others assign motive or mental state.' }
  ]
};
